INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-cost-optimized-architectures-v1-001', 'aws-saa', 'Uma empresa tem 50 TB de logs de aplicação: acessados com frequência nos primeiros 30 dias, ocasionalmente até 90 dias, e praticamente nunca depois disso — mas não podem ser apagados por 3 anos, por exigência regulatória. Qual estratégia minimiza custo sem gerenciamento manual constante?',
  '[{"id":"A","text":"Manter tudo em S3 Standard pelos 3 anos inteiros"},{"id":"B","text":"Uma política de ciclo de vida do S3 movendo automaticamente: Standard → Standard-IA aos 30 dias → Glacier Deep Archive aos 90 dias, expirando aos 3 anos"},{"id":"C","text":"Apagar os logs manualmente todo mês para economizar espaço"},{"id":"D","text":"Mover tudo para EBS, que é mais barato que S3"}]'::jsonb, 'B',
  '{
    "summary": "O padrão de acesso decrescente ao longo do tempo é exatamente o que uma política de ciclo de vida do S3 automatiza.",
    "whyCorrect": "A política de ciclo de vida transiciona o objeto automaticamente entre classes de armazenamento conforme a idade dele — sem intervenção manual — reduzindo custo por GB à medida que o acesso se torna menos frequente, e ainda aplica a expiração no prazo regulatório exato.",
    "whyWrong": {
     "A": "Manter tudo em Standard pelos 3 anos paga o preço mais alto por GB do início ao fim, mesmo depois que o acesso praticamente cessa — desperdício direto de custo.",
     "C": "Apagar manualmente violaria a exigência regulatória de retenção de 3 anos, além de depender de disciplina humana recorrente e sujeita a erro.",
     "D": "EBS não é mais barato que as classes frias do S3 (Glacier, Deep Archive) para este padrão, e é armazenamento de BLOCO amarrado a instância — modelo de custo e de uso completamente diferente do de arquivo de log de longo prazo."
    },
    "keyConcept": "Políticas de ciclo de vida do S3 e transição automática entre classes"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
