INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-cost-optimized-architectures-v1-002', 'aws-saa', 'Uma aplicação transfere 200 TB de dados de um data center on-premises para a AWS, uma única vez, como parte de uma migração. A conexão de internet disponível é de 100 Mbps. Qual opção de transferência é a mais econômica e rápida para este caso único?',
  '[{"id":"A","text":"Transferir pela internet usando a conexão de 100 Mbps disponível, que levaria mais de 180 dias"},{"id":"B","text":"AWS Direct Connect, contratado só para esta transferência única"},{"id":"C","text":"Um dispositivo AWS Snowball, enviado fisicamente com o dado copiado localmente e devolvido à AWS"},{"id":"D","text":"Comprimir os arquivos e tentar novamente pela mesma conexão"}]'::jsonb, 'C',
  '{
    "summary": "Para volume grande e transferência ÚNICA com link lento, mover o dado fisicamente é mais rápido que mover pela rede.",
    "whyCorrect": "Com 100 Mbps, 200 TB levariam mais de meio ano pela rede — inviável. O Snowball copia o dado localmente em alta velocidade e é enviado fisicamente à AWS para ingestão, completando a transferência em dias, não meses, sem exigir upgrade de link para um evento único.",
    "whyWrong": {
     "A": "O próprio enunciado calcula o tempo — mais de 180 dias — que é claramente inviável para uma migração; é a alternativa que ilustra por que rede não escala para esse volume com esse link.",
     "B": "Contratar Direct Connect — que envolve provisionamento de circuito físico dedicado, tipicamente com prazo de semanas para ativação — só para UM evento de transferência única é desproporcional em custo e tempo de setup comparado ao Snowball.",
     "D": "Compressão reduz o volume, mas não resolve a limitação fundamental de 100 Mbps de forma suficiente para tornar meses em dias — o gargalo continua sendo a largura de banda do link."
    },
    "keyConcept": "AWS Snowball para transferência de grande volume com link limitado"
   }'::jsonb,
  '', '', 'hard', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
