INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-cost-optimized-architectures-v1-003', 'aws-saa', 'Um bucket S3 recebe milhões de objetos pequenos por dia, com padrão de acesso totalmente imprevisível — alguns objetos são lidos minutos depois de criados, outros só meses depois, sem um padrão claro. A equipe não quer criar regra de ciclo de vida manual baseada em suposição. Qual classe resolve?',
  '[{"id":"A","text":"S3 Standard, sempre"},{"id":"B","text":"S3 One Zone-IA, para todos os objetos, sem exceção"},{"id":"C","text":"Apagar os objetos após 24 horas para evitar o problema"},{"id":"D","text":"S3 Intelligent-Tiering, que move o objeto automaticamente entre camadas com base no padrão de acesso REAL observado"}]'::jsonb, 'D',
  '{
    "summary": "Padrão de acesso IMPREVISÍVEL é o caso de uso que justifica Intelligent-Tiering em vez de regra de ciclo de vida fixa baseada em suposição.",
    "whyCorrect": "Intelligent-Tiering monitora o padrão de acesso de CADA objeto e o move automaticamente entre camadas de custo sem que a equipe precise ADIVINHAR o comportamento — resolvendo exatamente o problema descrito de imprevisibilidade sem intervenção manual.",
    "whyWrong": {
     "A": "S3 Standard paga o preço mais alto para todo objeto, inclusive os que não são acessados por meses — sem otimização para o padrão descrito.",
     "B": "One Zone-IA reduz durabilidade (uma única AZ) e é pensado para dado reproduzível de acesso pouco frequente CONHECIDO — aplicá-lo a TODO objeto, incluindo os de acesso imediato e imprevisível, é inadequado e arriscado.",
     "C": "Apagar após 24h destrói dado que ainda pode ser necessário meses depois, conforme o próprio enunciado descreve — não é uma estratégia de custo, é perda de dado."
    },
    "keyConcept": "S3 Intelligent-Tiering para padrão de acesso imprevisível"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
