INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-cost-optimized-architectures-v1-004', 'aws-saa', 'Uma carga de processamento em lote (não crítica, tolerante a interrupção) pode ser reagendada se a capacidade for interrompida, e a empresa quer o MENOR custo possível de instância EC2 para essa carga. Qual modelo de compra é o mais barato?',
  '[{"id":"A","text":"Spot Instances, aproveitando capacidade ociosa da AWS com desconto de até 90% em relação ao On-Demand"},{"id":"B","text":"On-Demand, pagando o preço cheio por hora"},{"id":"C","text":"Reserved Instances de 3 anos, pagamento adiantado total"},{"id":"D","text":"Savings Plans de compute, com compromisso de 1 ano"}]'::jsonb, 'A',
  '{
    "summary": "Carga tolerante a interrupção é exatamente o perfil que Spot Instances foram desenhadas para atender, com o maior desconto entre as opções.",
    "whyCorrect": "Spot Instances usam capacidade ociosa da AWS a até 90% de desconto sobre On-Demand — a contrapartida é que a AWS pode reivindicar a capacidade de volta com pouco aviso, o que o enunciado já declara como aceitável para essa carga específica.",
    "whyWrong": {
     "B": "On-Demand é o preço de REFERÊNCIA, sem nenhum desconto — a alternativa mais cara da lista, quando a carga descrita nem precisa da garantia que o On-Demand oferece.",
     "C": "Reserved Instances de 3 anos economiza sobre On-Demand, mas exige COMPROMISSO de longo prazo — inadequado para uma carga batch esporádica e tolerante a interrupção, que não precisa de reserva de capacidade garantida.",
     "D": "Savings Plans também exige compromisso de USO CONSISTENTE por 1 ano; para uma carga tolerante a interrupção e sem padrão de uso constante, Spot continua sendo mais barato e mais adequado ao perfil descrito."
    },
    "keyConcept": "Spot Instances para carga tolerante a interrupção"
   }'::jsonb,
  '', '', 'easy', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
  stem          = EXCLUDED.stem,
