INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-cost-optimized-architectures-v1-005', 'aws-saa', 'Uma empresa roda uma frota de instâncias EC2 24 horas por dia, 365 dias por ano, para uma carga de trabalho ESTÁVEL e previsível (o mesmo servidor de aplicação, sempre ligado). Qual modelo de compra reduz custo sem exigir troca de tipo específico de instância?',
  '[{"id":"A","text":"Spot Instances, aceitando o risco de interrupção para essa carga sempre ativa"},{"id":"B","text":"Savings Plans de compute, que dá desconto em troca de compromisso de gasto por hora, com flexibilidade entre famílias e regiões"},{"id":"C","text":"Continuar pagando On-Demand integralmente"},{"id":"D","text":"Desligar a instância todo fim de semana"}]'::jsonb, 'B',
  '{
    "summary": "Uso constante e previsível é justamente o padrão em que um compromisso de gasto (Savings Plans) rende desconto sem o risco de interrupção do Spot.",
    "whyCorrect": "Savings Plans de compute dá desconto significativo em troca de um compromisso de valor gasto por hora (não de tipo específico de instância), com flexibilidade para mudar família de instância ou região — adequado a uma carga sempre ativa e sem risco de interrupção que o Spot introduziria.",
    "whyWrong": {
     "A": "Spot Instances correm risco de interrupção a qualquer momento — inadequado para uma carga que precisa estar SEMPRE ativa, como o enunciado descreve explicitamente.",
     "C": "On-Demand integral é o preço cheio, sem nenhum desconto — desperdiça a economia disponível justamente para o padrão de uso mais PREVISÍVEL possível, que é o cenário ideal para obter desconto por compromisso.",
     "D": "Desligar nos fins de semana contradiz o enunciado, que descreve a carga como rodando 24x7 o ano inteiro — não é uma opção compatível com o requisito declarado."
    },
    "keyConcept": "Savings Plans para carga de trabalho estável e previsível"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
  stem          = EXCLUDED.stem,
