INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-cost-optimized-architectures-v1-006', 'aws-saa', 'Uma aplicação roda em um Auto Scaling Group com instâncias On-Demand fixas, mesmo durante os vales de tráfego noturno, quando 80% da capacidade fica ociosa. Qual ajuste reduz custo sem impactar a disponibilidade nos picos?',
  '[{"id":"A","text":"Manter o número fixo de instâncias, para simplificar operação"},{"id":"B","text":"Migrar tudo para uma única instância gigante, sempre ligada"},{"id":"C","text":"Configurar scaling baseado em métrica (como CPU ou número de requisições), reduzindo o número de instâncias automaticamente nos vales e aumentando nos picos"},{"id":"D","text":"Desligar o Auto Scaling Group completamente"}]'::jsonb, 'C',
  '{
    "summary": "Escala dinâmica por métrica é o mecanismo que elimina especificamente a capacidade ociosa nos vales, sem sacrificar capacidade nos picos.",
    "whyCorrect": "Configurar o Auto Scaling Group para reagir a uma métrica real de demanda reduz o número de instâncias quando o tráfego cai (economizando nos vales) e aumenta automaticamente quando o tráfego sobe (preservando disponibilidade nos picos) — resolvendo os dois lados do problema ao mesmo tempo.",
    "whyWrong": {
     "A": "Número fixo mantém o desperdício descrito no enunciado — 80% de capacidade ociosa à noite continua sendo paga integralmente, sem nenhuma economia.",
     "B": "Uma única instância gigante remove a elasticidade e cria um ponto único de falha — nem resolve o desperdício noturno (ela continua ligada o tempo todo) nem melhora a disponibilidade.",
     "D": "Desligar o Auto Scaling Group elimina tanto a economia automática nos vales quanto a capacidade de resposta automática nos picos — o oposto do que se busca."
    },
    "keyConcept": "Auto Scaling dinâmico por métrica para eliminar capacidade ociosa"
   }'::jsonb,
  '', '', 'easy', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
