INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-cost-optimized-architectures-v1-007', 'aws-saa', 'Uma aplicação nova terá tráfego totalmente imprevisível nos primeiros meses — pode ser zero por dias e picos súbitos sem aviso. A empresa não quer pagar por capacidade de banco de dados ociosa nem correr risco de subdimensionar. Qual opção de capacidade do Amazon Aurora atende?',
  '[{"id":"A","text":"Uma instância Aurora provisionada de tamanho fixo, dimensionada para o pico esperado"},{"id":"B","text":"Migrar para um banco on-premises, fora da AWS"},{"id":"C","text":"Provisionar duas instâncias grandes, uma de cada tipo, por precaução"},{"id":"D","text":"Aurora Serverless v2, escalando a capacidade automaticamente conforme a demanda real, cobrando pelo uso"}]'::jsonb, 'D',
  '{
    "summary": "Tráfego imprevisível, de zero a pico súbito, é o caso de uso definidor do Aurora Serverless.",
    "whyCorrect": "Aurora Serverless v2 ajusta a capacidade automaticamente em resposta à carga real, em segundos, cobrando pelo uso efetivo — elimina tanto o custo de capacidade ociosa nos períodos de baixo tráfego quanto o risco de subdimensionamento nos picos súbitos.",
    "whyWrong": {
     "A": "Dimensionar para o PICO esperado paga aquele tamanho o tempo todo, inclusive nos \"dias sem tráfego\" que o enunciado descreve — desperdício direto de custo na maior parte do tempo.",
     "B": "Migrar para fora da AWS é uma mudança de infraestrutura completamente desproporcional ao problema, que é apenas sobre elasticidade de capacidade de banco de dados.",
     "C": "Duas instâncias grandes \"por precaução\" dobra o custo fixo sem resolver o problema central, que é a IMPREVISIBILIDADE — o desperdício de capacidade ociosa persiste, só que em dobro."
    },
    "keyConcept": "Amazon Aurora Serverless v2 para carga imprevisível"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
