INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-cost-optimized-architectures-v1-008', 'aws-saa', 'Uma aplicação de IoT grava telemetria de milhões de dispositivos com padrão de acesso simples (chave-valor) e tráfego que varia enormemente entre dias úteis e fins de semana. A empresa não quer gerenciar capacidade manualmente nem pagar por capacidade fixa nos períodos de baixa. Qual modo de capacidade do DynamoDB é o mais adequado?',
  '[{"id":"A","text":"DynamoDB On-Demand, cobrando por requisição real sem necessidade de prever ou gerenciar capacidade"},{"id":"B","text":"Capacidade provisionada fixa, dimensionada para o pico dos dias úteis"},{"id":"C","text":"Migrar a telemetria para um banco relacional tradicional"},{"id":"D","text":"Reduzir a capacidade provisionada manualmente todo fim de semana, à mão"}]'::jsonb, 'A',
  '{
    "summary": "Tráfego variável e imprevisível entre dias, sem querer gerenciar capacidade manualmente, é o cenário que o modo On-Demand resolve diretamente.",
    "whyCorrect": "O DynamoDB On-Demand cobra por requisição de leitura e escrita efetivamente realizada, escalando automaticamente para cima e para baixo sem que a equipe preveja capacidade ou intervenha manualmente entre dias úteis e fins de semana.",
    "whyWrong": {
     "B": "Capacidade fixa dimensionada para o pico dos dias úteis paga esse teto TODOS os dias, inclusive nos fins de semana de tráfego baixo — desperdício direto que o requisito quer evitar.",
     "C": "Migrar de motor de banco é uma mudança desproporcional para resolver um problema que é puramente de MODELO DE CAPACIDADE, não de tipo de dado ou de padrão de acesso.",
     "D": "Ajuste manual recorrente é exatamente o esforço operacional que o requisito pede para evitar — \"sem gerenciar capacidade manualmente\" descarta essa alternativa por definição."
    },
    "keyConcept": "DynamoDB On-Demand vs capacidade provisionada"
   }'::jsonb,
  '', '', 'easy', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
