INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-cost-optimized-architectures-v1-009', 'aws-saa', 'Uma VPC tem instâncias em três Availability Zones diferentes, cada uma com seu próprio NAT Gateway, gerando custo fixo por hora em CADA AZ, mesmo que o tráfego de saída seja pequeno. A empresa aceita reduzir resiliência entre AZs para cortar custo. O que reduz o número de NAT Gateways cobrados sem eliminar totalmente o acesso à internet das sub-redes privadas?',
  '[{"id":"A","text":"Remover todos os NAT Gateways, eliminando o acesso à internet das sub-redes privadas"},{"id":"B","text":"Consolidar em um único NAT Gateway compartilhado entre as três AZs, aceitando que uma falha da AZ dele afete o tráfego de saída das outras"},{"id":"C","text":"Aumentar a capacidade do NAT Gateway existente"},{"id":"D","text":"Migrar todas as instâncias para sub-redes públicas"}]'::jsonb, 'B',
  '{
    "summary": "A troca explícita aceita pelo enunciado é resiliência por custo — um único NAT Gateway compartilhado é a forma direta de reduzir o custo fixo por AZ.",
    "whyCorrect": "Um único NAT Gateway, numa única AZ, compartilhado pelas sub-redes das três zonas via roteamento entre elas, reduz o custo fixo de \"um NAT por AZ\" para \"um NAT total\" — ao custo aceito pelo enunciado de que uma falha daquela AZ específica afetaria a saída das outras duas.",
    "whyWrong": {
     "A": "Remover TODOS os NAT Gateways elimina o custo, mas também elimina completamente o acesso à internet das sub-redes privadas — o enunciado pede reduzir custo MANTENDO algum acesso, não eliminá-lo.",
     "C": "Aumentar capacidade do NAT existente não reduz o NÚMERO de NAT Gateways cobrados — cada AZ continuaria com o seu próprio, mantendo o custo fixo por AZ que se quer reduzir.",
     "D": "Migrar para sub-rede pública expõe as instâncias diretamente à internet, o que muda o modelo de segurança de forma desproporcional só para resolver um problema de custo de rede."
    },
    "keyConcept": "Trade-off entre NAT Gateway por AZ (resiliência) e NAT compartilhado (custo)"
   }'::jsonb,
  '', '', 'hard', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
