INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-cost-optimized-architectures-v1-010', 'aws-saa', 'Uma aplicação transfere grandes volumes de dado entre duas instâncias EC2 na MESMA Availability Zone, e a equipe percebe que está sendo cobrada por transferência de dado que ela esperava ser gratuita. O que provavelmente explica o custo, e como evitá-lo?',
  '[{"id":"A","text":"Transferência de dado dentro da mesma AZ é sempre cobrada, sem exceção possível"},{"id":"B","text":"O problema é sempre do NAT Gateway, mesmo sem ele estar no caminho"},{"id":"C","text":"As instâncias provavelmente estão se comunicando via endereço IP PÚBLICO em vez do IP privado; usar o IP privado dentro da mesma AZ costuma ser gratuito"},{"id":"D","text":"É impossível reduzir esse custo de nenhuma forma"}]'::jsonb, 'C',
  '{
    "summary": "O padrão mais comum de cobrança inesperada em transferência intra-AZ é tráfego roteado por IP público quando o IP privado bastaria.",
    "whyCorrect": "Comunicação entre instâncias na MESMA AZ usando endereço IP PRIVADO normalmente não gera custo de transferência de dado. Se a cobrança está ocorrendo, a causa mais comum é a aplicação estar usando o IP PÚBLICO (ou DNS público) das instâncias, que roteia o tráfego de forma diferente e pode incorrer em custo.",
    "whyWrong": {
     "A": "Transferência dentro da mesma AZ via IP privado é tipicamente gratuita — a afirmação de que \"é sempre cobrada, sem exceção\" está incorreta e ignora exatamente a configuração que evitaria o custo.",
     "B": "Se o NAT Gateway não está no caminho da comunicação entre as duas instâncias (que estão na mesma VPC), ele não é a causa — atribuir a ele sem verificar o caminho de rede real é diagnóstico apressado.",
     "D": "Existe sim uma forma direta de reduzir esse custo especificamente — trocar para IP privado — o que torna esta alternativa factualmente incorreta diante da causa mais provável."
    },
    "keyConcept": "Transferência de dado intra-AZ: IP privado vs IP público"
   }'::jsonb,
  '', '', 'hard', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
