INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-cost-optimized-architectures-v1-011', 'aws-saa', 'Uma empresa mantém snapshots automáticos diários de um banco RDS há 4 anos, sem nunca ter revisado a política de retenção, e a conta de armazenamento de snapshot cresceu continuamente. O que provavelmente está acontecendo, e qual ajuste corrige sem perder capacidade de recuperação recente?',
  '[{"id":"A","text":"Snapshots automáticos são gratuitos para sempre, então o custo deve ser de outra origem"},{"id":"B","text":"É preciso apagar o banco de dados inteiro para parar o custo"},{"id":"C","text":"Snapshot não tem custo de armazenamento, então a causa é outra coisa"},{"id":"D","text":"Snapshots acumulam indefinidamente sem uma política de retenção definida; configurar um período de retenção (ex.: manter só os últimos 35 dias) elimina o acúmulo sem perder recuperação recente"}]'::jsonb, 'D',
  '{
    "summary": "Snapshot RDS SEM retenção configurada se acumula indefinidamente, e cada um tem custo de armazenamento proporcional ao tamanho.",
    "whyCorrect": "Sem um período de retenção explícito, snapshots automáticos diários se acumulam ano após ano, cada um cobrando armazenamento incremental. Configurar retenção (por exemplo, manter só os últimos 35 dias) apaga automaticamente os mais antigos, cortando o custo sem sacrificar a capacidade de restaurar um estado recente.",
    "whyWrong": {
     "A": "Snapshot de RDS TEM custo de armazenamento proporcional ao volume de dado alterado desde o snapshot anterior — não é gratuito indefinidamente, e essa é justamente a causa mais provável do crescimento descrito.",
     "B": "Apagar o banco de dados INTEIRO resolveria o custo de forma desproporcional e destrutiva — o requisito é sobre gerenciar RETENÇÃO de snapshot, não sobre eliminar o banco de produção.",
     "C": "Repetir que não há custo de armazenamento contradiz o próprio modelo de cobrança do RDS para snapshot, e não investiga a causa real descrita no cenário."
    },
    "keyConcept": "Retenção de snapshot RDS e custo de armazenamento acumulado"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
