INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-cost-optimized-architectures-v1-012', 'aws-saa', 'Duas VPCs de times diferentes, na mesma região, trocam volume alto de dado entre si diariamente. Hoje o tráfego passa pela internet pública via IPs elásticos, gerando custo de transferência e exposição desnecessária. Qual mudança reduz custo de transferência e mantém o tráfego dentro da rede da AWS?',
  '[{"id":"A","text":"VPC Peering entre as duas VPCs, roteando o tráfego pela rede privada da AWS em vez da internet pública"},{"id":"B","text":"Continuar como está, já que VPCs diferentes não podem se conectar de outra forma"},{"id":"C","text":"Migrar as duas VPCs para a mesma conta, sem nenhuma outra mudança de rede"},{"id":"D","text":"Aumentar a banda do link de internet de cada VPC"}]'::jsonb, 'A',
  '{
    "summary": "VPC Peering conecta duas VPCs diretamente pela rede da AWS, eliminando a necessidade de sair para a internet pública para esse tráfego.",
    "whyCorrect": "Com VPC Peering, o tráfego entre as duas VPCs passa a rotear pela rede interna da AWS — normalmente com custo de transferência menor que o de sair e voltar pela internet pública — além de eliminar a exposição de IP elástico público para esse tráfego interno.",
    "whyWrong": {
     "B": "VPCs diferentes PODEM sim se conectar de forma privada — Peering, Transit Gateway ou PrivateLink são exatamente os mecanismos para isso; afirmar o contrário ignora a solução disponível.",
     "C": "Estar na mesma CONTA não muda automaticamente o caminho de rede entre duas VPCs — ainda seria necessário Peering ou outro mecanismo de conexão para tirar o tráfego da internet pública.",
     "D": "Aumentar banda da internet melhora VELOCIDADE, mas mantém o tráfego saindo para a internet pública — não resolve nem o custo de transferência associado nem a exposição que o Peering elimina."
    },
    "keyConcept": "VPC Peering para reduzir custo e exposição de tráfego entre VPCs"
   }'::jsonb,
  '', '', 'hard', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
