INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-performing-architectures-v1-001', 'aws-saa', 'Uma aplicação de renderização de vídeo precisa que MÚLTIPLAS instâncias EC2, ao mesmo tempo, leiam e gravem no MESMO conjunto de arquivos compartilhado, com semântica de sistema de arquivos POSIX. Qual serviço de armazenamento atende?',
  '[{"id":"A","text":"Amazon EBS, anexado a uma única instância"},{"id":"B","text":"Amazon EFS, montado simultaneamente por todas as instâncias que precisam do acesso compartilhado"},{"id":"C","text":"Amazon S3, tratado como um sistema de arquivos POSIX"},{"id":"D","text":"Instance store local de cada instância"}]'::jsonb, 'B',
  '{
    "summary": "Acesso concorrente por múltiplas instâncias, com semântica POSIX, é o caso de uso definidor do EFS.",
    "whyCorrect": "O EFS é um sistema de arquivos de REDE que pode ser montado por milhares de instâncias EC2 simultaneamente, com semântica POSIX completa — leitura e escrita concorrente no mesmo arquivo funcionam como um sistema de arquivos tradicional compartilhado.",
    "whyWrong": {
     "A": "EBS é armazenamento de BLOCO anexado a UMA ÚNICA instância por vez (fora do modo multi-attach, que é caso especial e não POSIX geral) — não atende \"múltiplas instâncias\" do jeito descrito.",
     "C": "S3 é armazenamento de OBJETO, acessado via API HTTP, sem semântica POSIX nativa (sem lock de arquivo, sem escrita parcial no meio do arquivo) — não é o que \"sistema de arquivos compartilhado\" pede.",
     "D": "Instance store é LOCAL e EFÊMERO à instância — nenhuma outra instância enxerga esse armazenamento, o oposto de compartilhado."
    },
    "keyConcept": "Amazon EFS para acesso compartilhado multi-instância"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
  stem          = EXCLUDED.stem,
  options       = EXCLUDED.options,
  correct_id    = EXCLUDED.correct_id,
  explanation   = EXCLUDED.explanation,
  topic         = EXCLUDED.topic,
  domain        = EXCLUDED.domain,
  difficulty    = EXCLUDED.difficulty,
