INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-performing-architectures-v1-002', 'aws-saa', 'Um banco de dados transacional em uma instância EC2 precisa do menor tempo de resposta possível de disco (baixa latência, alto IOPS), e a aplicação já trata a instância como descartável, recriando o dado a partir de outra fonte se a instância falhar. Qual tipo de armazenamento oferece a menor latência?',
  '[{"id":"A","text":"Amazon S3 Standard"},{"id":"B","text":"Amazon EFS"},{"id":"C","text":"Instance store (NVMe SSD local à instância física)"},{"id":"D","text":"Amazon EBS sc1 (HDD de baixo custo)"}]'::jsonb, 'C',
  '{
    "summary": "Instance store é fisicamente local ao host — sem salto de rede — e por isso é a opção de MENOR latência entre as listadas.",
    "whyCorrect": "Instance store fica no disco físico do próprio host que roda a instância, sem passar pela rede como EBS ou EFS fazem — isso entrega a menor latência possível. O trade-off, aceito aqui pelo enunciado, é que o dado se perde se a instância parar ou for encerrada.",
    "whyWrong": {
     "A": "S3 é acessado via API HTTP sobre a rede, com latência de dezenas de milissegundos — ordens de grandeza mais lento que disco local para uma carga transacional latência-sensível.",
     "B": "EFS é armazenamento de REDE (protocolo NFS); mesmo otimizado, tem latência de rede maior que disco físico local, e não é o perfil ideal para banco transacional de latência mínima.",
     "D": "sc1 é uma classe de EBS otimizada para CUSTO em cargas sequenciais de baixo IOPS — é o oposto do perfil pedido, que é baixa latência e alto IOPS."
    },
    "keyConcept": "Instance store vs EBS vs EFS: onde cada um vence em latência"
   }'::jsonb,
  '', '', 'hard', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
  stem          = EXCLUDED.stem,
  options       = EXCLUDED.options,
  correct_id    = EXCLUDED.correct_id,
  explanation   = EXCLUDED.explanation,
  topic         = EXCLUDED.topic,
  domain        = EXCLUDED.domain,
  difficulty    = EXCLUDED.difficulty,
