INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-performing-architectures-v1-003', 'aws-saa', 'Uma empresa mantém 500 TB de arquivos raramente acessados (auditoria de anos anteriores) e quer o menor custo de armazenamento possível, aceitando um tempo de recuperação de HORAS quando eventualmente precisar acessar algo. Qual classe de armazenamento S3 é a mais econômica para esse padrão?',
  '[{"id":"A","text":"S3 Standard"},{"id":"B","text":"S3 Standard-IA"},{"id":"C","text":"S3 Intelligent-Tiering"},{"id":"D","text":"S3 Glacier Deep Archive"}]'::jsonb, 'D',
  '{
    "summary": "Quanto maior a tolerância ao tempo de recuperação, menor o custo por GB — e Deep Archive é o extremo mais barato dessa curva.",
    "whyCorrect": "Glacier Deep Archive é a classe de MENOR custo por GB do S3, desenhada justamente para dado raramente acessado com tempo de recuperação de horas aceitável — exatamente o padrão descrito de arquivo de auditoria antigo.",
    "whyWrong": {
     "A": "S3 Standard é otimizado para acesso FREQUENTE, com o maior custo por GB entre as opções — inadequado e caro para um dado acessado raramente.",
     "B": "Standard-IA é mais barato que Standard, mas ainda mais caro que Deep Archive, e é pensado para dado acessado ocasionalmente com recuperação em MILISSEGUNDOS — não para um caso que tolera horas.",
     "C": "Intelligent-Tiering move o objeto automaticamente entre camadas com base no padrão de acesso, o que tem seu valor quando o padrão é IMPREVISÍVEL — mas para um padrão já CONHECIDO como raramente acessado, ir direto ao Deep Archive é mais barato que pagar a taxa de monitoramento do Intelligent-Tiering."
    },
    "keyConcept": "Classes de armazenamento S3 por padrão de acesso e custo"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
  stem          = EXCLUDED.stem,
