INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-performing-architectures-v1-004', 'aws-saa', 'Uma aplicação de simulação científica precisa de processamento paralelo massivo com placas de vídeo (GPU) para treinar modelos, e o workload sobe e desce conforme a fila de trabalhos batch enviados pelos pesquisadores. Qual combinação de serviços atende com menor esforço operacional?',
  '[{"id":"A","text":"AWS Batch, com instâncias EC2 com GPU, escalando conforme a fila de jobs"},{"id":"B","text":"Uma única instância EC2 com GPU sempre ligada, mesmo sem trabalho na fila"},{"id":"C","text":"AWS Lambda, que não oferece GPU"},{"id":"D","text":"Amazon EFS para armazenar os resultados, sem nenhum serviço de compute dedicado"}]'::jsonb, 'A',
  '{
    "summary": "AWS Batch existe especificamente para gerenciar fila de trabalho batch, provisionando e desprovisionando compute conforme a demanda.",
    "whyCorrect": "O AWS Batch gerencia a fila de jobs, provisiona instâncias EC2 com GPU sob demanda quando há trabalho pendente, e as desliga quando a fila esvazia — sem que a equipe escreva lógica própria de escala para o cluster de processamento batch.",
    "whyWrong": {
     "B": "Instância sempre ligada, mesmo ociosa, paga por capacidade não utilizada na maior parte do tempo — o oposto de eficiência para um workload que \"sobe e desce\".",
     "C": "Lambda de fato não oferece GPU dedicada nesse contexto de simulação pesada, então está corretamente descartada — mas isso sozinho não resolve o problema; é preciso um serviço que ofereça GPU E gerencie a fila, que é o Batch.",
     "D": "EFS resolve armazenamento compartilhado de resultado, não o PROCESSAMENTO com GPU nem o gerenciamento da fila de trabalho — responde a uma pergunta diferente da que foi feita."
    },
    "keyConcept": "AWS Batch para processamento em lote com GPU"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
  stem          = EXCLUDED.stem,
