INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-performing-architectures-v1-005', 'aws-saa', 'Uma API precisa responder consistentemente em menos de 50ms mesmo sob carga variável, e o time quer minimizar o número de "cold starts" que penalizam a latência de funções serverless pouco usadas. Qual configuração do Lambda ajuda diretamente com isso?',
  '[{"id":"A","text":"Aumentar o timeout máximo da função para 15 minutos"},{"id":"B","text":"Configurar Provisioned Concurrency, mantendo um número de execuções já inicializadas prontas para responder"},{"id":"C","text":"Reduzir a memória alocada à função para o mínimo"},{"id":"D","text":"Remover todas as variáveis de ambiente da função"}]'::jsonb, 'B',
  '{
    "summary": "Provisioned Concurrency existe exatamente para eliminar o atraso de inicialização (cold start) em funções sensíveis à latência.",
    "whyCorrect": "Provisioned Concurrency mantém um número configurado de ambientes de execução JÁ INICIALIZADOS, prontos para receber invocação imediatamente — elimina o tempo de cold start para essas execuções, o que é essencial quando o SLA de latência é apertado.",
    "whyWrong": {
     "A": "Timeout máximo define quanto tempo uma execução pode DURAR antes de ser interrompida; não tem relação com o tempo de INICIALIZAÇÃO (cold start) da função.",
     "C": "Reduzir memória geralmente PIORA a performance de CPU (que é proporcional à memória no Lambda) e não reduz cold start — pode até alongá-lo em funções com dependência pesada para carregar.",
     "D": "Variáveis de ambiente têm impacto desprezível no tempo de inicialização comparado ao carregamento de runtime e dependências — não é o que causa cold start relevante."
    },
    "keyConcept": "Provisioned Concurrency e cold start no AWS Lambda"
   }'::jsonb,
  '', '', 'hard', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
  stem          = EXCLUDED.stem,
  options       = EXCLUDED.options,
  correct_id    = EXCLUDED.correct_id,
