INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-performing-architectures-v1-006', 'aws-saa', 'Uma aplicação processa vídeo e é limitada por CPU: mais núcleos de processamento aceleram diretamente o tempo de codificação. Ao escolher o tipo de instância EC2, qual família é a mais adequada?',
  '[{"id":"A","text":"Uma família memory optimized (como a série R), priorizando RAM"},{"id":"B","text":"Uma família de armazenamento denso (como a série D), priorizando disco"},{"id":"C","text":"Uma família compute optimized (como a série C), com alta relação de vCPU por custo"},{"id":"D","text":"Qualquer família, porque o tipo de instância não afeta workload de CPU"}]'::jsonb, 'C',
  '{
    "summary": "Workload limitado por CPU aponta diretamente para a família compute optimized.",
    "whyCorrect": "A série compute optimized (C) oferece a maior proporção de poder de processamento por custo entre as famílias — exatamente o que uma carga de codificação de vídeo limitada por CPU precisa para acelerar diretamente com mais núcleos.",
    "whyWrong": {
     "A": "Memory optimized prioriza RAM por vCPU, útil para banco em memória ou cache grande — não é o gargalo descrito, que é processamento, não memória.",
     "B": "Storage optimized prioriza IOPS de disco local, útil para banco de dado transacional intensivo em disco — não ataca o gargalo de CPU do enunciado.",
     "D": "A escolha de família tem impacto direto e mensurável em cargas com gargalo específico; ignorar isso é o erro central que a questão testa — nem toda instância entrega a mesma relação de custo-benefício para o mesmo tipo de carga."
    },
    "keyConcept": "Famílias de instância EC2 por perfil de carga: compute, memory, storage optimized"
   }'::jsonb,
  '', '', 'easy', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
