INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-performing-architectures-v1-007', 'aws-saa', 'Uma aplicação de e-commerce tem um catálogo de produtos consultado com padrão de acesso key-value simples (buscar produto por ID) e precisa de latência de milissegundos de um único dígito em qualquer escala de tráfego. Qual tipo de banco é o mais adequado?',
  '[{"id":"A","text":"Amazon RDS para PostgreSQL, com uma instância grande"},{"id":"B","text":"Um data warehouse como o Amazon Redshift"},{"id":"C","text":"Um único arquivo CSV armazenado no S3"},{"id":"D","text":"Amazon DynamoDB, um banco NoSQL gerenciado com latência de milissegundos de um único dígito em qualquer escala"}]'::jsonb, 'D',
  '{
    "summary": "Acesso key-value simples, com necessidade de latência consistente em qualquer escala, é o perfil de uso central do DynamoDB.",
    "whyCorrect": "DynamoDB é desenhado especificamente para acesso key-value e de baixa latência PREVISÍVEL — de milissegundos de um único dígito — independentemente de o tráfego ser 10 ou 10 milhões de requisições, sem a equipe gerenciar servidor de banco.",
    "whyWrong": {
     "A": "RDS relacional é excelente para consulta com JOIN e transação complexa, mas para um padrão puramente key-value ele carrega overhead relacional desnecessário e não escala latência tão previsivelmente quanto o DynamoDB nesse padrão específico.",
     "B": "Redshift é um DATA WAREHOUSE otimizado para consulta analítica sobre grande volume histórico — o oposto de latência de milissegundo para consulta pontual por chave, que é o requisito aqui.",
     "C": "Arquivo CSV no S3 não tem índice, não responde consulta por chave em milissegundos, e exigiria ler o arquivo inteiro ou construir um índice externo — não atende o requisito de latência nem de escala."
    },
    "keyConcept": "Amazon DynamoDB para acesso key-value de baixa latência"
   }'::jsonb,
  '', '', 'easy', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
