INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-performing-architectures-v1-008', 'aws-saa', 'Um banco de dados relacional está sob carga de leitura pesada e repetitiva — as mesmas consultas de "produtos em destaque" rodam milhares de vezes por minuto, sempre retornando o mesmo resultado por alguns minutos seguidos. Qual mudança reduz a carga no banco sem alterar a lógica de consulta?',
  '[{"id":"A","text":"Introduzir uma camada de cache com Amazon ElastiCache na frente do banco, para as consultas repetidas"},{"id":"B","text":"Adicionar mais réplicas de leitura, apenas"},{"id":"C","text":"Aumentar o tamanho da instância do banco"},{"id":"D","text":"Reescrever a consulta para não usar índice"}]'::jsonb, 'A',
  '{
    "summary": "Consulta repetida com resultado estável por período é o caso canônico de cache — resolve na origem, não só distribui a carga.",
    "whyCorrect": "ElastiCache (Redis ou Memcached) armazena o resultado da consulta em memória por um período (TTL); chamadas repetidas dentro desse período são respondidas pelo cache, sem tocar o banco — reduzindo a carga na ORIGEM, não só redistribuindo entre réplicas.",
    "whyWrong": {
     "B": "Mais réplicas de leitura distribuem a carga entre mais bancos, mas cada consulta repetida ainda EXECUTA no banco — não elimina o trabalho redundante que o cache elimina.",
     "C": "Aumentar a instância paga por mais capacidade para continuar executando a MESMA consulta repetidamente — trata o sintoma com mais recurso, em vez de eliminar o trabalho redundante.",
     "D": "Remover índice torna a consulta mais LENTA, piorando a carga em vez de aliviá-la — é o oposto do que se busca."
    },
    "keyConcept": "Amazon ElastiCache para reduzir carga de leitura repetitiva"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
