INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-performing-architectures-v1-009', 'aws-saa', 'Uma aplicação precisa migrar de um banco Oracle on-premises para o Amazon Aurora PostgreSQL, com o MENOR tempo de indisponibilidade possível durante o corte, incluindo conversão de esquema entre motores diferentes. Quais serviços da AWS resolvem essa migração heterogênea?',
  '[{"id":"A","text":"Apenas copiar os arquivos de dado brutos do Oracle para o Aurora"},{"id":"B","text":"AWS Schema Conversion Tool (SCT) para converter o esquema, e AWS Database Migration Service (DMS) para migrar e replicar os dados com downtime mínimo"},{"id":"C","text":"Recriar manualmente todo o esquema e reinserir os dados um a um via aplicação"},{"id":"D","text":"Amazon RDS Proxy, sozinho"}]'::jsonb, 'B',
  '{
    "summary": "Migração heterogênea (motores diferentes) é o caso de uso conjunto de SCT (esquema) e DMS (dado).",
    "whyCorrect": "O SCT converte objetos de esquema do dialeto Oracle para o dialeto PostgreSQL, incluindo o que não converte automaticamente e precisa de ação manual; o DMS migra os dados e pode manter replicação contínua até o corte final, minimizando o tempo de indisponibilidade.",
    "whyWrong": {
     "A": "Copiar arquivo bruto não funciona entre motores DIFERENTES — o formato interno do Oracle é incompatível com o do PostgreSQL/Aurora; migração heterogênea exige conversão, não cópia direta.",
     "C": "Reinserir manualmente registro a registro via aplicação é inviável em escala de produção e não oferece garantia de consistência nem controle de tempo de corte.",
     "D": "RDS Proxy gerencia POOL DE CONEXÃO após a migração estar pronta; ele não converte esquema nem migra dado — resolve um problema diferente do de migração."
    },
    "keyConcept": "AWS SCT e DMS para migração heterogênea de banco de dados"
   }'::jsonb,
  '', '', 'hard', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
