INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-performing-architectures-v1-010', 'aws-saa', 'Uma aplicação de análise de sessão de usuário precisa armazenar e consultar dados de série temporal em altíssimo volume (milhões de pontos por segundo), com consulta por intervalo de tempo. Qual tipo de banco tem melhor ajuste a esse padrão específico?',
  '[{"id":"A","text":"Um banco relacional genérico como PostgreSQL, sem otimização específica"},{"id":"B","text":"Amazon S3 Glacier"},{"id":"C","text":"Amazon Timestream, um banco gerenciado especializado em série temporal"},{"id":"D","text":"Amazon Route 53"}]'::jsonb, 'C',
  '{
    "summary": "Dado de série temporal em altíssimo volume tem um banco AWS dedicado, desenhado especificamente para esse padrão.",
    "whyCorrect": "Timestream é otimizado especificamente para ingestão e consulta de dado com carimbo de tempo em altíssimo volume, com compressão e particionamento automáticos por tempo — uma vantagem estrutural sobre um banco relacional genérico para esse padrão de acesso.",
    "whyWrong": {
     "A": "PostgreSQL genérico PODE armazenar série temporal, mas sem otimização dedicada de compressão e particionamento por tempo, degrada em volume muito alto — não é o \"melhor ajuste\" que a pergunta pede.",
     "B": "Glacier é armazenamento de ARQUIVO frio, sem capacidade de consulta indexada por intervalo de tempo em tempo real — não atende o padrão de consulta descrito.",
     "D": "Route 53 é serviço de DNS, sem relação nenhuma com armazenamento ou consulta de dado de série temporal."
    },
    "keyConcept": "Amazon Timestream para dado de série temporal em alto volume"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
