INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-performing-architectures-v1-011', 'aws-saa', 'Uma aplicação recebe tráfego UDP de altíssimo volume para um jogo online multiplayer, e precisa da menor latência possível de rede na camada de transporte, sem inspeção de conteúdo de aplicação. Qual tipo de load balancer é o mais adequado?',
  '[{"id":"A","text":"Application Load Balancer (ALB), operando na camada 7"},{"id":"B","text":"Classic Load Balancer, sem suporte a UDP"},{"id":"C","text":"Nenhum load balancer, distribuindo via DNS round-robin manual"},{"id":"D","text":"Network Load Balancer (NLB), operando na camada 4 com latência ultra baixa e suporte a UDP"}]'::jsonb, 'D',
  '{
    "summary": "UDP e latência mínima na camada de transporte apontam diretamente para o Network Load Balancer.",
    "whyCorrect": "O NLB opera na camada 4 (transporte), suporta UDP nativamente, e é desenhado para latência extremamente baixa e altíssimo throughput — exatamente o perfil de um jogo multiplayer que não precisa de inspeção de conteúdo HTTP.",
    "whyWrong": {
     "A": "ALB opera na camada 7 (aplicação), entende HTTP/HTTPS e faz roteamento baseado em conteúdo — mas NÃO suporta UDP, que é o protocolo explicitamente citado no requisito.",
     "B": "Classic Load Balancer é o tipo legado, sem suporte a UDP e sem a otimização de latência do NLB — inadequado tecnicamente para o requisito.",
     "C": "DNS round-robin manual não reage à saúde dos backends, não distribui com a granularidade de um load balancer real, e reintroduz o trabalho operacional que o serviço gerenciado evita."
    },
    "keyConcept": "Network Load Balancer para UDP e latência mínima"
   }'::jsonb,
  '', '', 'hard', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
  stem          = EXCLUDED.stem,
