INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-performing-architectures-v1-012', 'aws-saa', 'Uma aplicação hospeda seu backend em duas regiões AWS diferentes e quer que o usuário seja automaticamente roteado para o endpoint SAUDÁVEL de menor latência, com failover em segundos (mais rápido que a propagação típica de TTL de DNS). Qual serviço atende?',
  '[{"id":"A","text":"AWS Global Accelerator, usando a rede de borda da AWS e IPs anycast fixos para rotear e falhar rapidamente entre regiões"},{"id":"B","text":"Apenas registros DNS padrão do Route 53 com TTL baixo"},{"id":"C","text":"Amazon CloudFront, sozinho, sem nenhuma configuração de origem múltipla"},{"id":"D","text":"AWS Direct Connect entre as duas regiões"}]'::jsonb, 'A',
  '{
    "summary": "Failover mais rápido que propagação de DNS é justamente o que o Global Accelerator resolve, usando IP fixo em vez de resolução de nome.",
    "whyCorrect": "O Global Accelerator usa IPs anycast estáticos e a rede de borda global da AWS para rotear o tráfego para o endpoint mais próximo e saudável; como o roteamento acontece na camada de rede, não depende de o cliente resolver DNS de novo — o failover é da ordem de segundos, não do tempo de propagação de TTL.",
    "whyWrong": {
     "B": "Mesmo com TTL baixo, o cliente ainda depende de resolver o DNS de novo e de caches de resolvers intermediários respeitarem o TTL — na prática, mais lento e menos confiável que o Global Accelerator para este requisito.",
     "C": "CloudFront acelera entrega de CONTEÚDO (cache), e pode ter múltiplas origens configuradas, mas o cenário descrito — failover rápido entre regiões de BACKEND ativo — é o caso de uso central do Global Accelerator, não do CloudFront isolado.",
     "D": "Direct Connect é conectividade dedicada de data center para AWS; não tem relação com rotear USUÁRIOS PÚBLICOS entre regiões."
    },
    "keyConcept": "AWS Global Accelerator vs DNS para failover rápido entre regiões"
   }'::jsonb,
  '', '', 'hard', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
  stem          = EXCLUDED.stem,
  options       = EXCLUDED.options,
