INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-performing-architectures-v1-013', 'aws-saa', 'Uma arquitetura em VPC precisa que instâncias em uma sub-rede privada alcancem o Amazon S3 SEM passar por um NAT Gateway (para reduzir custo de processamento de dado do NAT) e sem sair para a internet pública. Qual recurso resolve especificamente para o S3?',
  '[{"id":"A","text":"Um Interface VPC Endpoint para todo tráfego da VPC"},{"id":"B","text":"Um Gateway VPC Endpoint para o S3, sem custo de processamento de dado"},{"id":"C","text":"Aumentar a capacidade do NAT Gateway"},{"id":"D","text":"Tornar a sub-rede pública"}]'::jsonb, 'B',
  '{
    "summary": "Para S3 e DynamoDB especificamente, o Gateway Endpoint é gratuito e elimina a necessidade do NAT Gateway para esse tráfego.",
    "whyCorrect": "O Gateway VPC Endpoint é o tipo específico usado para S3 e DynamoDB: ele adiciona uma rota na tabela de rotas da sub-rede apontando diretamente para o serviço, sem custo de processamento de dado por GB e sem que o tráfego passe pelo NAT Gateway.",
    "whyWrong": {
     "A": "Interface Endpoint (via PrivateLink) é o tipo usado para a MAIORIA dos outros serviços AWS, mas para S3 e DynamoDB especificamente, o Gateway Endpoint é a opção sem custo adicional de processamento — usar Interface aqui incorreria em custo desnecessário.",
     "C": "Aumentar o NAT Gateway aumenta capacidade, mas mantém o CUSTO de processamento de dado por GB que o requisito quer evitar — não resolve o objetivo de reduzir esse custo.",
     "D": "Tornar a sub-rede pública contradiz o requisito de manter a sub-rede privada e de não sair para a internet pública."
    },
    "keyConcept": "Gateway VPC Endpoint (S3/DynamoDB) vs Interface VPC Endpoint"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
  stem          = EXCLUDED.stem,
  options       = EXCLUDED.options,
