INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-performing-architectures-v1-014', 'aws-saa', 'Uma empresa recebe um fluxo contínuo de eventos de clique de usuário (centenas de milhares por segundo) que precisa ser capturado em tempo real e entregue para análise, com a possibilidade de múltiplos consumidores lerem o MESMO fluxo de forma independente. Qual serviço atende?',
  '[{"id":"A","text":"Amazon SQS Standard Queue"},{"id":"B","text":"AWS Glue, sozinho"},{"id":"C","text":"Amazon Kinesis Data Streams, permitindo múltiplos consumidores lerem o mesmo stream de forma independente"},{"id":"D","text":"Um bucket S3 recebendo um arquivo por evento individual"}]'::jsonb, 'C',
  '{
    "summary": "Múltiplos consumidores lendo o MESMO fluxo, de forma independente e em alta taxa, é o padrão que o Kinesis Data Streams resolve — SQS não permite isso da mesma forma.",
    "whyCorrect": "Kinesis Data Streams retém o dado por um período configurável e permite que MÚLTIPLOS consumidores leiam o stream inteiro de forma independente, cada um na sua própria posição — diferente de uma fila, onde uma mensagem consumida geralmente sai da fila para os demais.",
    "whyWrong": {
     "A": "SQS Standard entrega cada mensagem a UM consumidor por vez (dentro do modelo de fila); múltiplos consumidores independentes lendo o MESMO conjunto de eventos não é o padrão nativo do SQS sem arquitetura adicional de fan-out.",
     "B": "Glue é ferramenta de ETL em LOTE (ou streaming ETL sobre uma fonte), não um serviço de INGESTÃO de fluxo em tempo real por si só — ele processaria dado de uma fonte como o Kinesis, não substitui a captura do fluxo.",
     "D": "Um arquivo por evento individual no S3 gera centenas de milhares de arquivos pequenos por segundo — o antipadrão de \"muitos arquivos pequenos\", caro e lento para consultar depois."
    },
    "keyConcept": "Amazon Kinesis Data Streams e consumidores independentes"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
