INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-performing-architectures-v1-015', 'aws-saa', 'Uma equipe de dados recebe arquivos CSV brutos e precisa transformá-los para Parquet, com deduplicação e enriquecimento com dados de outra tabela, antes de disponibilizar para consulta analítica — sem gerenciar servidor de processamento. Qual serviço atende?',
  '[{"id":"A","text":"Copiar os arquivos CSV originais para outro bucket, sem transformação"},{"id":"B","text":"Amazon Route 53"},{"id":"C","text":"Rodar um script Python manualmente na máquina de um analista, uma vez por semana"},{"id":"D","text":"AWS Glue, com jobs de ETL serverless em Spark gerenciado"}]'::jsonb, 'D',
  '{
    "summary": "ETL serverless com transformação e enriquecimento é o caso de uso central do AWS Glue.",
    "whyCorrect": "O Glue executa jobs de ETL em Spark totalmente gerenciado — sem que a equipe provisione cluster —, suportando transformação de formato (CSV para Parquet), deduplicação e junção com outras fontes para enriquecimento, com o resultado disponível para consulta analítica.",
    "whyWrong": {
     "A": "Copiar sem transformar não atende NENHUM dos requisitos (conversão de formato, deduplicação, enriquecimento) — resolve só o transporte, não a transformação pedida.",
     "B": "Route 53 é serviço de DNS — resolve nome de domínio para endereço IP — e não tem nenhuma capacidade de processar, transformar ou armazenar dado de arquivo.",
     "C": "Script manual numa máquina de analista, rodado semanalmente, não escala, é frágil a falha humana, e contradiz \"sem gerenciar servidor de processamento\" — a máquina do analista É um servidor não gerenciado nesse sentido."
    },
    "keyConcept": "AWS Glue para ETL serverless"
   }'::jsonb,
  '', '', 'easy', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
  stem          = EXCLUDED.stem,
