INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-performing-architectures-v1-016', 'aws-saa', 'Uma empresa quer permitir que analistas de negócio consultem, de forma ad-hoc e sem gerenciar infraestrutura, arquivos Parquet armazenados diretamente no S3, usando SQL padrão. Qual serviço atende com menor esforço operacional?',
  '[{"id":"A","text":"Amazon Athena, consultando diretamente os arquivos no S3 via SQL, sem servidor"},{"id":"B","text":"Provisionar um cluster Redshift permanente, mesmo para consultas esporádicas"},{"id":"C","text":"Baixar todos os arquivos Parquet para a máquina de cada analista"},{"id":"D","text":"Amazon Polly"}]'::jsonb, 'A',
  '{
    "summary": "Consulta SQL ad-hoc direta sobre arquivo no S3, sem infraestrutura para gerenciar, é o caso de uso definidor do Athena.",
    "whyCorrect": "Athena é um serviço de consulta SERVERLESS que roda SQL padrão diretamente sobre arquivos no S3 (incluindo Parquet), cobrando por dado escaneado — sem que a equipe provisione ou gerencie nenhum cluster, ideal para consulta ad-hoc e esporádica.",
    "whyWrong": {
     "B": "Um cluster Redshift permanente incorre em custo fixo mesmo quando ocioso, e provisionamento/gerenciamento de cluster é exatamente o esforço operacional que o requisito quer evitar para uma consulta esporádica.",
     "C": "Baixar arquivos para a máquina local não escala, perde controle de acesso centralizado, e não é uma solução de consulta analítica — é um retrocesso operacional.",
     "D": "Polly é um serviço de síntese de voz — converte texto escrito em áudio falado — e não tem nenhuma relação com consulta ou análise de dado."
    },
    "keyConcept": "Amazon Athena para consulta SQL serverless sobre S3"
   }'::jsonb,
  '', '', 'easy', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
  stem          = EXCLUDED.stem,
