  difficulty    = EXCLUDED.difficulty,
  scenario_type = EXCLUDED.scenario_type,
  tags          = EXCLUDED.tags,
  source        = EXCLUDED.source,
  status        = 'active',
  updated_at    = now();

INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-resilient-architectures-v1-001', 'aws-saa', 'Um serviço de processamento de pedidos falha ocasionalmente ao chamar um serviço de estoque, e quando falha, o pedido inteiro é perdido. A empresa quer que o pedido seja RETIDO e reprocessado automaticamente, sem que o serviço de pedidos precise saber se o de estoque está disponível no momento. Qual padrão resolve?',
  '[{"id":"A","text":"Desacoplar via Amazon SQS: o serviço de pedidos publica na fila, e o serviço de estoque consome quando estiver disponível"},{"id":"B","text":"Chamar o serviço de estoque diretamente via HTTP síncrono, com retry no código"},{"id":"C","text":"Aumentar o timeout da chamada HTTP para 10 minutos"},{"id":"D","text":"Colocar os dois serviços na mesma instância EC2"}]'::jsonb, 'A',
  '{
    "summary": "Fila de mensagens é o mecanismo de desacoplamento temporal — quem publica não precisa que quem consome esteja disponível no mesmo instante.",
    "whyCorrect": "Com SQS entre os dois serviços, o pedido é PERSISTIDO na fila assim que publicado. Se o serviço de estoque estiver indisponível, a mensagem simplesmente espera até ele voltar e consumir — nada se perde, e o serviço de pedidos nunca precisa saber do estado do outro.",
    "whyWrong": {
     "B": "Retry no código síncrono ainda faz o pedido depender da disponibilidade IMEDIATA do serviço de estoque; se todas as tentativas falharem, o pedido se perde do mesmo jeito.",
     "C": "Aumentar timeout só prolonga a espera síncrona; não resolve a perda quando o serviço de estoque está genuinamente fora do ar por mais tempo que o timeout, e mantém o acoplamento temporal.",
     "D": "Colocar na mesma instância cria acoplamento físico — os dois falham juntos, e não resolve a questão de disponibilidade nem de desacoplamento lógico entre os serviços."
    },
    "keyConcept": "Amazon SQS e desacoplamento assíncrono entre serviços"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
