INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-resilient-architectures-v1-002', 'aws-saa', 'Um evento de "pedido criado" precisa disparar três ações independentes: enviar e-mail, atualizar um data warehouse e notificar um parceiro externo. Se um consumidor adicionar um QUARTO interessado no futuro, a aplicação publicadora não deve precisar de nenhuma mudança. Qual padrão atende?',
  '[{"id":"A","text":"O serviço publicador chama diretamente as três APIs, uma de cada vez"},{"id":"B","text":"Publicar o evento em um tópico Amazon SNS, com os três (e futuros) consumidores inscritos independentemente"},{"id":"C","text":"Duplicar o código do publicador três vezes, um para cada consumidor"},{"id":"D","text":"Fazer os três consumidores consultarem um banco de dados a cada 1 segundo (polling)"}]'::jsonb, 'B',
  '{
    "summary": "Fan-out via SNS é o padrão pub/sub: o publicador não conhece nem precisa mudar quando consumidores são adicionados.",
    "whyCorrect": "O publicador manda UMA mensagem ao tópico SNS; cada assinante (e-mail, warehouse, parceiro) recebe uma cópia de forma independente. Um novo interessado se inscreve no tópico sem que o código do publicador mude em nada — é exatamente o desacoplamento que o requisito pede.",
    "whyWrong": {
     "A": "Chamar as três APIs diretamente acopla o publicador a cada consumidor: adicionar um quarto exige alterar o código do publicador, o oposto do requisito.",
     "C": "Duplicar código por consumidor multiplica manutenção e ainda exige mudança no publicador a cada novo interessado — mesmo problema do item A, com esforço extra.",
     "D": "Polling a cada segundo sobrecarrega o banco com consultas majoritariamente vazias, introduz atraso até 1 segundo por natureza, e não escala bem à medida que mais consumidores fazem polling do mesmo estado."
    },
    "keyConcept": "Padrão fan-out com Amazon SNS"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
