INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-resilient-architectures-v1-003', 'aws-saa', 'Uma aplicação recebe picos de tráfego imprevisíveis de zero a 10.000 requisições por segundo, e a empresa não quer administrar servidor nem pagar por capacidade ociosa nos períodos de baixo tráfego. Qual arquitetura de computação é a mais adequada?',
  '[{"id":"A","text":"Um cluster fixo de instâncias EC2 dimensionado para o pico"},{"id":"B","text":"Uma única instância EC2 grande, sempre ligada"},{"id":"C","text":"AWS Lambda atrás de Amazon API Gateway, escalando automaticamente por invocação"},{"id":"D","text":"Um cluster ECS com número fixo de tarefas"}]'::jsonb, 'C',
  '{
    "summary": "Tráfego imprevisível de zero a pico extremo, sem querer gerenciar servidor, é o caso canônico de serverless.",
    "whyCorrect": "Lambda escala automaticamente por invocação — de zero a milhares de execuções concorrentes — sem provisionamento prévio, e cobra só pelo tempo de execução real. Não há servidor para administrar nem capacidade ociosa paga durante os vales de tráfego.",
    "whyWrong": {
     "A": "Cluster fixo dimensionado para o pico paga por capacidade ociosa na maior parte do tempo, que é exatamente o que a empresa quer evitar — e ainda exige administração de servidor.",
     "B": "Uma instância grande sempre ligada tem um teto de capacidade e ainda cobra o tempo inteiro, mesmo nos vales — nem elástico nem eficiente em custo para esse padrão de tráfego.",
     "D": "ECS com número FIXO de tarefas não se ajusta automaticamente ao pico de 10.000 req/s sem configuração de auto scaling adicional, e mesmo com ela, ainda envolve gerenciar infraestrutura de cluster que o Lambda dispensa."
    },
    "keyConcept": "AWS Lambda para tráfego elástico e imprevisível"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
  stem          = EXCLUDED.stem,
