INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-resilient-architectures-v1-004', 'aws-saa', 'Uma aplicação de microsserviços precisa escalar cada serviço de forma INDEPENDENTE — o serviço de checkout recebe 10x mais tráfego que o de catálogo. Qual característica de design os microsserviços devem ter para permitir isso?',
  '[{"id":"A","text":"Todos os microsserviços compartilhando a mesma instância de banco de dados e o mesmo processo"},{"id":"B","text":"Um monólito único que engloba toda a lógica de negócio"},{"id":"C","text":"Serviços que armazenam sessão de usuário na memória local da instância"},{"id":"D","text":"Serviços stateless, cada um com seu próprio grupo de escala, comunicando-se por API ou fila em vez de memória compartilhada"}]'::jsonb, 'D',
  '{
    "summary": "Escala independente por serviço exige que cada um seja isolado e sem estado preso à instância.",
    "whyCorrect": "Serviços stateless, com grupo de auto scaling próprio e comunicação via API/fila, permitem que o checkout escale para 50 instâncias enquanto o catálogo permanece em 5 — cada um dimensionado pela sua própria demanda, sem carregar o outro junto.",
    "whyWrong": {
     "A": "Compartilhar instância de banco e processo cria acoplamento: escalar um serviço competiria por recurso com os outros, e uma falha de um afeta todos — o oposto de escala independente.",
     "B": "Monólito escala como uma unidade só — não há como dar 10x mais capacidade só ao checkout sem escalar a aplicação inteira, desperdiçando recurso no catálogo.",
     "C": "Sessão presa à instância (sticky, em memória local) impede escalar horizontalmente sem quebrar sessões existentes, e amarra o usuário a uma instância específica — atrapalha justamente a elasticidade que o requisito pede."
    },
    "keyConcept": "Microsserviços stateless e escala independente"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
