INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-resilient-architectures-v1-005', 'aws-saa', 'Um site de e-commerce quer reduzir a latência de entrega de imagens de produto para usuários no mundo todo, sem replicar manualmente o conteúdo em cada região. Qual serviço resolve?',
  '[{"id":"A","text":"Amazon CloudFront como CDN na frente do S3, fazendo cache nas edge locations mais próximas do usuário"},{"id":"B","text":"Replicar o bucket S3 manualmente em cada continente"},{"id":"C","text":"Aumentar o tamanho da instância EC2 que serve as imagens"},{"id":"D","text":"Comprimir as imagens no navegador do cliente"}]'::jsonb, 'A',
  '{
    "summary": "Latência global de conteúdo estático é o problema que uma CDN existe para resolver.",
    "whyCorrect": "CloudFront faz cache do conteúdo do S3 nas edge locations espalhadas globalmente; o usuário recebe a imagem do ponto de presença mais próximo dele, sem que a empresa precise replicar dado manualmente em cada região.",
    "whyWrong": {
     "B": "Replicação manual por continente é operacionalmente cara, exige lógica de roteamento própria e reinventa o que uma CDN já resolve de forma gerenciada.",
     "C": "Tamanho de instância EC2 não resolve latência GEOGRÁFICA — o servidor continua numa única região, e um usuário do outro lado do mundo ainda percorre a distância física até ele.",
     "D": "Compressão no cliente reduz tamanho de arquivo, não a distância física entre o usuário e a origem do dado — ataca uma dimensão diferente do problema de latência."
    },
    "keyConcept": "Amazon CloudFront como CDN"
   }'::jsonb,
  '', '', 'easy', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
