INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-resilient-architectures-v1-006', 'aws-saa', 'Uma aplicação legada monolítica está sendo migrada para contêineres. A empresa quer rodar os contêineres sem gerenciar servidor nem cluster de EC2 subjacente. Qual combinação de serviços atende?',
  '[{"id":"A","text":"Amazon ECS com EC2 launch type, gerenciando os servidores manualmente"},{"id":"B","text":"Amazon ECS ou EKS com AWS Fargate como tipo de capacidade"},{"id":"C","text":"Rodar Docker diretamente numa instância EC2 sem orquestrador"},{"id":"D","text":"AWS Lambda executando os mesmos contêineres sem nenhuma mudança"}]'::jsonb, 'B',
  '{
    "summary": "Fargate é o tipo de capacidade que remove o servidor subjacente da equação, com ECS ou EKS como orquestrador.",
    "whyCorrect": "ECS ou EKS com Fargate orquestra os contêineres SEM que a equipe provisione, corrija ou dimensione instâncias EC2 — a AWS gerencia a infraestrutura de execução, e o time só define CPU e memória da tarefa.",
    "whyWrong": {
     "A": "EC2 launch type exige que a equipe gerencie o cluster de instâncias que hospeda os contêineres — patch, dimensionamento, capacidade — o oposto de \"sem gerenciar servidor\".",
     "C": "Docker direto numa instância, sem orquestrador, ainda exige administrar a instância manualmente e perde recursos de orquestração como reinício automático e balanceamento entre tarefas.",
     "D": "Lambda tem limites de execução e modelo de invocação diferentes de um contêiner de aplicação de longa duração; migrar \"sem nenhuma mudança\" para Lambda normalmente não é viável para uma aplicação monolítica de longa duração."
    },
    "keyConcept": "AWS Fargate: contêiner sem gerenciar servidor"
   }'::jsonb,
  '', '', 'hard', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
