INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-resilient-architectures-v1-007', 'aws-saa', 'Um processo de aprovação de empréstimo tem 6 etapas sequenciais, cada uma com lógica condicional (se reprovado, pula para notificação; se aprovado, segue para desembolso). A empresa quer visibilidade de em qual etapa cada solicitação está, com retry automático por etapa. Qual serviço orquestra isso?',
  '[{"id":"A","text":"Uma fila SQS única processando tudo em sequência dentro de uma função Lambda gigante"},{"id":"B","text":"Um cron job rodando a cada minuto e verificando o estado no banco"},{"id":"C","text":"AWS Step Functions, modelando o processo como uma máquina de estados com lógica condicional por etapa"},{"id":"D","text":"EventBridge sozinho, sem nenhuma lógica de estado"}]'::jsonb, 'C',
  '{
    "summary": "Fluxo sequencial e condicional com visibilidade por etapa é o caso de uso central do Step Functions.",
    "whyCorrect": "O Step Functions modela cada etapa como um estado da máquina, com transição condicional nativa (Choice state) e retry configurável POR ETAPA — e o console mostra visualmente em qual estado cada execução está, o que o requisito de visibilidade pede diretamente.",
    "whyWrong": {
     "A": "Uma função Lambda gigante controlando 6 etapas mistura toda a lógica de estado num único bloco de código, sem visibilidade individual de progresso e sem retry granular por etapa — difícil de depurar e de estender.",
     "B": "Cron verificando estado no banco a cada minuto introduz atraso de até 1 minuto por transição e reconstrói manualmente o que o Step Functions já oferece nativamente, com mais código e mais pontos de falha.",
     "D": "EventBridge roteia evento, mas não modela ESTADO nem SEQUÊNCIA de etapas por si só; usá-lo sozinho para orquestrar 6 etapas condicionais exigiria reconstruir a máquina de estados por fora."
    },
    "keyConcept": "AWS Step Functions para orquestração de workflow"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
  stem          = EXCLUDED.stem,
