INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-resilient-architectures-v1-008', 'aws-saa', 'Uma aplicação precisa armazenar arquivos de vídeo grandes (vários GB cada) e acessá-los ocasionalmente para reprodução, com durabilidade alta e custo por GB competitivo. Qual tipo de armazenamento é o mais adequado?',
  '[{"id":"A","text":"Amazon EBS, anexado a uma única instância EC2"},{"id":"B","text":"Um banco de dados relacional, armazenando o vídeo como BLOB"},{"id":"C","text":"Memória RAM de uma instância, para acesso mais rápido"},{"id":"D","text":"Amazon S3, como armazenamento de objeto"}]'::jsonb, 'D',
  '{
    "summary": "Arquivo grande, acesso ocasional, alta durabilidade: é o perfil canônico de armazenamento de objeto.",
    "whyCorrect": "S3 foi desenhado para exatamente esse padrão — objeto de qualquer tamanho, durabilidade de 11 noves, custo por GB competitivo, e acessível de qualquer lugar via API sem estar amarrado a uma instância específica.",
    "whyWrong": {
     "A": "EBS é armazenamento de BLOCO amarrado a UMA instância EC2 numa Availability Zone; não é o padrão para arquivo acessado por múltiplos clientes nem para a escala de \"vários GB por arquivo, muitos arquivos\".",
     "B": "Armazenar vídeo como BLOB num banco relacional infla o banco, degrada performance de consulta do banco para outros dados, e custa por GB muito mais que armazenamento de objeto dedicado.",
     "C": "RAM é volátil (perde o dado ao reiniciar) e ordens de grandeza mais cara por GB — inviável para armazenamento durável de arquivo grande."
    },
    "keyConcept": "Amazon S3 como armazenamento de objeto"
   }'::jsonb,
  '', '', 'easy', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
  stem          = EXCLUDED.stem,
