INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-resilient-architectures-v1-009', 'aws-saa', 'Um banco de dados relacional está sendo sobrecarregado por consultas de LEITURA de um painel de relatórios, o que está degradando a performance de ESCRITA da aplicação principal. Qual mudança de arquitetura separa as duas cargas sem duplicar a lógica de escrita?',
  '[{"id":"A","text":"Criar uma ou mais read replicas e apontar o painel de relatórios para elas, mantendo a instância principal só para escrita"},{"id":"B","text":"Aumentar o tamanho da instância principal do banco"},{"id":"C","text":"Fazer o painel de relatórios consultar direto os arquivos de log do banco"},{"id":"D","text":"Migrar tudo para um banco NoSQL sem nenhuma outra mudança"}]'::jsonb, 'A',
  '{
    "summary": "Read replica existe exatamente para separar carga de leitura da carga de escrita, sem duplicar lógica de aplicação.",
    "whyCorrect": "Uma read replica recebe os dados replicados de forma assíncrona da instância principal; apontar o painel de relatórios para ela tira a carga de leitura pesada da instância principal, que fica livre para focar em escrita — sem que a aplicação precise duplicar lógica de gravação.",
    "whyWrong": {
     "B": "Aumentar o tamanho adia o problema, mas não SEPARA as duas cargas — leitura e escrita continuam competindo pelo mesmo recurso, só que num teto mais alto e mais caro.",
     "C": "Consultar arquivo de log diretamente não é um padrão de acesso a dado suportado para relatório; é frágil, sem garantia de consistência, e não resolve a contenção de recurso na instância.",
     "D": "Migrar de banco é uma mudança de arquitetura desproporcional ao problema, e \"sem nenhuma outra mudança\" ignora que o mesmo padrão de contenção entre leitura pesada e escrita pode se repetir no banco novo se a causa raiz não for endereçada."
    },
    "keyConcept": "Read replicas para separar carga de leitura e escrita"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
