INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-resilient-architectures-v1-010', 'aws-saa', 'Uma aplicação crítica roda em instâncias EC2 numa única Availability Zone. A empresa quer que a aplicação continue funcionando mesmo se essa AZ inteira ficar indisponível. Qual mudança mínima resolve?',
  '[{"id":"A","text":"Aumentar o número de instâncias, todas na mesma AZ"},{"id":"B","text":"Distribuir as instâncias em pelo menos duas Availability Zones, atrás de um Application Load Balancer"},{"id":"C","text":"Fazer backup diário das instâncias"},{"id":"D","text":"Migrar para uma instância maior na mesma AZ"}]'::jsonb, 'B',
  '{
    "summary": "Falha de UMA AZ só é tolerada se houver capacidade em OUTRA AZ pronta para atender.",
    "whyCorrect": "Distribuir as instâncias em duas ou mais AZs, com o ALB roteando tráfego entre elas, garante que a falha de uma AZ inteira deixe a(s) outra(s) atendendo — é a definição operacional de tolerância a falha de AZ.",
    "whyWrong": {
     "A": "Mais instâncias na MESMA AZ não ajuda em nada se a AZ inteira falhar — todas ficam indisponíveis juntas, porque a falha é da zona, não da capacidade individual.",
     "C": "Backup diário protege contra perda de DADO, não contra INDISPONIBILIDADE em tempo real — um backup não atende requisição de usuário enquanto não é restaurado, o que leva tempo.",
     "D": "Instância maior na mesma AZ aumenta capacidade, mas continua sujeita à mesma falha de zona — o problema é de distribuição geográfica dentro da região, não de tamanho de instância."
    },
    "keyConcept": "Multi-AZ como base de alta disponibilidade"
   }'::jsonb,
  '', '', 'easy', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
