INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-resilient-architectures-v1-011', 'aws-saa', 'Uma empresa precisa que, em caso de desastre que derrube a região primária inteira, a aplicação volte ao ar em MINUTOS, com perda de dado mínima, e está disposta a pagar por uma infraestrutura reduzida sempre ativa na região secundária. Qual estratégia de disaster recovery atende?',
  '[{"id":"A","text":"Backup and restore, sem nada rodando na região secundária"},{"id":"B","text":"Pilot light apenas com o banco de dados replicado, sem nenhum compute"},{"id":"C","text":"Warm standby: uma versão reduzida da aplicação rodando continuamente na região secundária, escalada em caso de failover"},{"id":"D","text":"Não ter nenhuma estratégia de DR e confiar na durabilidade do S3"}]'::jsonb, 'C',
  '{
    "summary": "RTO de minutos com custo controlado é o ponto de equilíbrio que warm standby ocupa entre pilot light e active-active.",
    "whyCorrect": "Warm standby mantém uma versão funcional, porém reduzida, sempre rodando na região secundária — no failover, basta ESCALAR a capacidade já existente, o que leva minutos, em vez de provisionar do zero. É o equilíbrio certo entre custo (menor que active-active) e RTO (menor que pilot light).",
    "whyWrong": {
     "A": "Backup and restore tem o RTO mais alto de todas as estratégias — provisionar infraestrutura do zero e restaurar dados leva horas, não minutos, o que não atende o requisito.",
     "B": "Pilot light com só o banco replicado e nenhum compute ainda exige provisionar toda a camada de aplicação no momento do desastre — mais rápido que backup and restore, mas mais lento que warm standby para o RTO de minutos pedido.",
     "D": "Ausência de estratégia de DR não atende requisito nenhum de RTO, e durabilidade de armazenamento (S3) não é o mesmo que disponibilidade de uma aplicação inteira em outra região."
    },
    "keyConcept": "Estratégias de disaster recovery: backup/restore, pilot light, warm standby, active-active"
   }'::jsonb,
  '', '', 'hard', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
