INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-resilient-architectures-v1-012', 'aws-saa', 'Uma aplicação usa Auto Scaling Group com verificação de saúde baseada apenas no status do EC2 (a instância está ligada). Instâncias que travam no nível da APLICAÇÃO, mas continuam com o sistema operacional respondendo, não são substituídas automaticamente. Qual ajuste corrige isso?',
  '[{"id":"A","text":"Aumentar o tempo de cooldown do Auto Scaling"},{"id":"B","text":"Reduzir o número mínimo de instâncias do grupo"},{"id":"C","text":"Desligar o Auto Scaling e gerenciar manualmente"},{"id":"D","text":"Trocar o health check do Auto Scaling Group para ELB, verificando a resposta real da aplicação via load balancer"}]'::jsonb, 'D',
  '{
    "summary": "Health check de EC2 só sabe se a MÁQUINA está viva; health check de ELB pergunta se a APLICAÇÃO responde.",
    "whyCorrect": "Ao configurar o health check do ASG como tipo ELB, o Auto Scaling passa a confiar na verificação de saúde do load balancer, que faz requisição real ao endpoint da aplicação — uma instância travada na aplicação, mesmo com o SO respondendo, falha essa checagem e é substituída.",
    "whyWrong": {
     "A": "Cooldown controla o INTERVALO entre ações de escala, não o CRITÉRIO usado para decidir se uma instância está saudável — não resolve o problema descrito.",
     "B": "Reduzir o mínimo de instâncias diminui capacidade disponível e não tem relação com detectar instância travada na aplicação — pode até piorar a disponibilidade.",
     "C": "Desligar o Auto Scaling remove a substituição automática por completo, o oposto de corrigir a detecção — perderia toda a capacidade de autorrecuperação, não só a parte que falha hoje."
    },
    "keyConcept": "Health check ELB vs EC2 no Auto Scaling Group"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
