INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-resilient-architectures-v1-013', 'aws-saa', 'Um site precisa direcionar usuários para a região AWS mais próxima geograficamente, e automaticamente redirecionar o tráfego para uma região secundária se a primária ficar indisponível, sem intervenção manual. Qual serviço faz esse roteamento baseado em saúde?',
  '[{"id":"A","text":"Amazon Route 53 com política de roteamento por latência ou geolocalização, e health checks associados"},{"id":"B","text":"Um arquivo hosts editado manualmente em cada cliente"},{"id":"C","text":"Um único registro DNS A fixo, apontando sempre para a região primária"},{"id":"D","text":"AWS Direct Connect, redirecionando o tráfego automaticamente"}]'::jsonb, 'A',
  '{
    "summary": "DNS com política de roteamento e health check é o mecanismo padrão de failover automático entre regiões.",
    "whyCorrect": "O Route 53 avalia o health check da região primária a cada intervalo; se ela falhar, o DNS passa a responder com o endpoint da região secundária automaticamente — combinado com política de latência ou geolocalização, também direciona cada usuário para a região mais próxima nas condições normais.",
    "whyWrong": {
     "B": "Editar arquivo hosts manualmente em cada cliente não escala para uma base de usuários real e não reage automaticamente a uma falha — é o oposto de automação.",
     "C": "Um registro DNS FIXO não tem nenhuma lógica de failover: se a região primária cair, o registro continua apontando para ela, e os usuários continuam recebendo erro.",
     "D": "Direct Connect é conectividade de REDE dedicada entre data center e AWS; ele não faz roteamento de DNS nem decide para qual região direcionar o tráfego de usuários públicos."
    },
    "keyConcept": "Amazon Route 53: roteamento por latência/geolocalização com health check"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
