INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-resilient-architectures-v1-014', 'aws-saa', 'Uma aplicação legada não foi construída para tolerar falha de conexão de banco de dados — quando a conexão cai, a aplicação trava até ser reiniciada manualmente. Sem alterar o código da aplicação, qual serviço da AWS melhora a resiliência dessa reconexão?',
  '[{"id":"A","text":"Reescrever a aplicação inteira do zero"},{"id":"B","text":"Amazon RDS Proxy, mantendo um pool de conexões e reconectando de forma transparente"},{"id":"C","text":"Aumentar o tamanho da instância do banco de dados"},{"id":"D","text":"Desabilitar o timeout de conexão no cliente"}]'::jsonb, 'B',
  '{
    "summary": "RDS Proxy é desenhado justamente para aplicação legada que não trata bem reconexão, sem exigir mudança de código.",
    "whyCorrect": "O RDS Proxy fica entre a aplicação e o banco, mantendo um pool de conexões gerenciado; em caso de failover do banco, ele lida com a reconexão de forma transparente, sem que a aplicação legada precise implementar lógica própria de retry.",
    "whyWrong": {
     "A": "O requisito explícito é \"sem alterar o código\" — reescrever é o oposto disso, além de ser desproporcional ao problema pontual de resiliência de conexão.",
     "C": "Tamanho de instância afeta capacidade de processamento, não o comportamento de reconexão da aplicação após uma queda momentânea de conexão.",
     "D": "Desabilitar timeout faz a aplicação esperar indefinidamente por uma conexão que pode nunca voltar sozinha — piora a experiência em vez de resolver a reconexão."
    },
    "keyConcept": "Amazon RDS Proxy para aplicações legadas"
   }'::jsonb,
  '', '', 'hard', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
