INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-resilient-architectures-v1-015', 'aws-saa', 'Uma equipe de operações precisa saber, com precisão, onde está o gargalo de latência quando uma requisição atravessa cinco microsserviços diferentes antes de responder ao usuário. Qual serviço dá essa visibilidade fim a fim?',
  '[{"id":"A","text":"Aumentar o nível de log para DEBUG em cada serviço, sem correlação entre eles"},{"id":"B","text":"Um dashboard genérico de CPU e memória de cada instância"},{"id":"C","text":"AWS X-Ray, rastreando a requisição através de todos os serviços"},{"id":"D","text":"Perguntar aos usuários onde eles percebem lentidão"}]'::jsonb, 'C',
  '{
    "summary": "X-Ray traça uma requisição individual através de múltiplos serviços, com tempo gasto em cada segmento.",
    "whyCorrect": "O X-Ray instrumenta cada serviço para propagar um identificador de rastreamento comum; o resultado é um mapa de serviço mostrando exatamente quanto tempo a requisição passou em CADA um dos cinco microsserviços, isolando o gargalo real.",
    "whyWrong": {
     "A": "Logs em DEBUG por serviço, sem correlação, exigem que alguém cruze manualmente timestamps de sistemas diferentes — lento, propenso a erro, e não dá o mapa fim a fim que o X-Ray entrega pronto.",
     "B": "CPU e memória mostram saturação de RECURSO da instância, não o CAMINHO nem o TEMPO da requisição específica através dos serviços — métrica diferente do que o requisito pede.",
     "D": "Percepção de usuário é qualitativa e não localiza QUAL dos cinco serviços é o gargalo — não substitui instrumentação técnica."
    },
    "keyConcept": "AWS X-Ray para rastreamento distribuído"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
