INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-resilient-architectures-v1-016', 'aws-saa', 'Uma aplicação armazena arquivos críticos em um único volume EBS anexado a uma instância EC2. A empresa quer garantir que, mesmo com falha do disco físico subjacente, o dado não seja perdido. O que já é verdade sobre o EBS, e o que ainda precisa ser adicionado?',
  '[{"id":"A","text":"EBS já protege contra falha de AZ inteira, nada mais é necessário"},{"id":"B","text":"EBS nunca falha, então nenhuma proteção adicional é necessária em nenhum cenário"},{"id":"C","text":"É preciso migrar para instance store, que é mais durável que EBS"},{"id":"D","text":"EBS replica automaticamente dentro da MESMA AZ (protegendo contra falha de disco físico); snapshots para S3 são necessários para proteger contra falha da AZ inteira"}]'::jsonb, 'D',
  '{
    "summary": "A durabilidade do EBS tem um escopo específico — dentro da AZ — que o candidato precisa saber onde termina.",
    "whyCorrect": "O EBS já replica os dados dentro da mesma Availability Zone, o que protege contra falha de disco físico isolado. Mas essa proteção não se estende a uma falha da AZ INTEIRA — para isso, snapshots (armazenados no S3, que é multi-AZ) são o mecanismo correto.",
    "whyWrong": {
     "A": "A replicação do EBS é DENTRO da AZ, não entre AZs — uma falha da AZ inteira ainda ameaçaria o volume e todos os seus snapshots não tirados; a afirmação exagera a proteção nativa.",
     "B": "Nenhum armazenamento é infalível; tratar EBS como imune a qualquer cenário de falha é a suposição perigosa que este item testa, e ela contradiz a própria documentação de durabilidade da AWS.",
     "C": "Instance store é EFÊMERO — o dado se perde quando a instância para ou é encerrada. É MENOS durável que EBS, não mais; a alternativa inverte a comparação."
    },
    "keyConcept": "Durabilidade do EBS: dentro da AZ vs entre AZs, e o papel do snapshot"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
