INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-resilient-architectures-v1-017', 'aws-saa', 'Uma aplicação depende de uma tabela DynamoDB que, em um teste de carga, começou a receber `ProvisionedThroughputExceededException` durante picos, mesmo com capacidade provisionada aparentemente suficiente na média do dia. Qual causa mais provável explica isso, e qual ajuste resolve sem superprovisionar o dia inteiro?',
  '[{"id":"A","text":"Partição quente: uma chave de partição concentra tráfego desproporcional; habilitar On-Demand ou redesenhar a chave de partição resolve"},{"id":"B","text":"O SDK está com bug; basta atualizar a versão"},{"id":"C","text":"A tabela precisa ser apagada e recriada do zero"},{"id":"D","text":"O problema é sempre de rede, não de capacidade"}]'::jsonb, 'A',
  '{
    "summary": "Throttling com capacidade média suficiente é a assinatura clássica de partição quente no DynamoDB.",
    "whyCorrect": "Capacidade provisionada é distribuída entre partições; se uma chave de partição concentra tráfego (por exemplo, um `tenant_id` de cliente muito ativo), aquela partição específica estoura seu limite mesmo com capacidade agregada de sobra — a correção é uma chave de partição com melhor distribuição de cardinalidade, ou mudar para capacidade On-Demand, que se adapta automaticamente.",
    "whyWrong": {
     "B": "A exceção reportada é do PRÓPRIO DynamoDB informando limite de capacidade excedido — não é uma falha de SDK, e atualizar versão não muda a distribuição de tráfego entre partições.",
     "C": "Apagar e recriar a tabela sem mudar o desenho da chave de partição reproduziria o mesmo problema assim que o tráfego voltasse ao mesmo padrão desigual.",
     "D": "A causa aqui é de CAPACIDADE por partição, não de rede — a mensagem de erro específica (`ProvisionedThroughputExceededException`) já aponta para throttling de capacidade, não para timeout de conectividade."
    },
    "keyConcept": "Partição quente no DynamoDB e capacidade On-Demand"
   }'::jsonb,
  '', '', 'hard', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
