INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-secure-architectures-v1-001', 'aws-saa', 'Uma empresa com 40 contas AWS organizadas por unidade de negócio precisa impedir que qualquer conta, mesmo com um administrador mal configurado, desligue o AWS CloudTrail ou saia da AWS Organizations. Qual controle atende?',
  '[{"id":"A","text":"Uma Service Control Policy (SCP) aplicada na Organizational Unit, negando as ações mesmo para o administrador local"},{"id":"B","text":"Uma role IAM com permissão de leitura em todas as contas"},{"id":"C","text":"Um alarme do CloudWatch que notifica quando o CloudTrail é desativado"},{"id":"D","text":"Uma política de senha forte exigida em todas as contas"}]'::jsonb, 'A',
  '{
    "summary": "SCP é o único controle que atua ACIMA do administrador de conta individual — nem o root local da conta membro consegue revogá-la.",
    "whyCorrect": "A SCP define o teto de permissões possível para toda a conta, incluindo o usuário root local. Negar `cloudtrail:StopLogging` e `organizations:LeaveOrganization` na SCP da OU torna essas ações impossíveis independentemente de qualquer política IAM criada dentro da conta membro.",
    "whyWrong": {
     "B": "Uma role de leitura ajuda auditoria, mas não IMPEDE nada — ela é permissiva, e o requisito é de bloqueio. Mesmo com a role, o administrador local mantém poder de desligar o CloudTrail via suas próprias permissões.",
     "C": "Um alarme é DETECTIVO: ele avisa depois que a ação já ocorreu. O requisito pede prevenção — impedir que aconteça, não ser notificado quando acontecer.",
     "D": "Senha forte protege contra acesso indevido à conta, mas não restringe o que um administrador LEGÍTIMO, já autenticado, pode fazer dentro dela — que é exatamente o cenário descrito."
    },
    "keyConcept": "Service Control Policies e o teto de permissões por OU",
    "realWorldContext": "Empresas com múltiplas contas usam SCP para impor guardrails organizacionais que sobrevivem a erro humano dentro de cada conta."
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
  stem          = EXCLUDED.stem,
