INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-secure-architectures-v1-002', 'aws-saa', 'Um time de dados em uma conta AWS precisa ler objetos de um bucket S3 que pertence a outro time, em outra conta, sem que as credenciais de longo prazo de nenhum dos dois times sejam compartilhadas. Qual abordagem é a recomendada?',
  '[{"id":"A","text":"Copiar a chave de acesso do dono do bucket para o time consumidor"},{"id":"B","text":"Criar uma role IAM na conta do bucket, com trust policy permitindo assumeRole pela conta consumidora, e política de bucket ou de role limitando ao prefixo necessário"},{"id":"C","text":"Tornar o bucket público e restringir por IP de origem"},{"id":"D","text":"Criar um usuário IAM compartilhado entre as duas contas"}]'::jsonb, 'B',
  '{
    "summary": "Acesso entre contas é o caso canônico de assumir role via STS, não de compartilhar credencial.",
    "whyCorrect": "Uma role com trust policy explícita para a conta consumidora, assumida via `sts:AssumeRole`, gera credenciais TEMPORÁRIAS por sessão — nenhuma chave de longo prazo atravessa a fronteira de conta, e o escopo pode ser restrito ao prefixo exato do objeto.",
    "whyWrong": {
     "A": "Copiar uma chave de acesso é exatamente o que a pergunta pede para EVITAR — credencial de longo prazo compartilhada é superfície de ataque permanente e sem rastreabilidade de qual sistema a usou.",
     "C": "Bucket público expõe o objeto à internet inteira; restringir por IP não impede acesso de fora daquele IP nem oferece controle de identidade — qualquer um naquele IP acessaria, sem autenticação.",
     "D": "Usuário IAM compartilhado entre contas não é um padrão suportado nativamente da forma pretendida, e mesmo que fosse viável, reintroduziria credencial de longo prazo compartilhada — o problema que o assumeRole resolve."
    },
    "keyConcept": "Acesso entre contas via IAM role e AWS STS",
    "compareWith": [
     "Resource policy vs identity policy para acesso cross-account"
    ]
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
