INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-secure-architectures-v1-003', 'aws-saa', 'Uma aplicação corporativa já usa Active Directory on-premises para autenticar 3.000 funcionários. A empresa quer que esses funcionários acessem o AWS Management Console sem criar 3.000 usuários IAM. Qual solução atende com menor esforço operacional?',
  '[{"id":"A","text":"Criar um usuário IAM para cada funcionário com a mesma senha do AD"},{"id":"B","text":"Migrar todos os funcionários para o AWS Directory Service e abandonar o AD on-premises"},{"id":"C","text":"Federar o Active Directory com IAM usando SAML 2.0 (ou AWS IAM Identity Center), fornecendo acesso temporário via role federada"},{"id":"D","text":"Compartilhar uma única credencial de administrador entre os funcionários que precisam de acesso"}]'::jsonb, 'C',
  '{
    "summary": "Federação é o padrão para reaproveitar um provedor de identidade existente sem duplicar usuários.",
    "whyCorrect": "A federação SAML (ou IAM Identity Center integrado ao AD) permite que o funcionário se autentique no AD e receba credenciais temporárias da AWS via role federada — sem criar nem manter 3.000 usuários IAM, e sem duplicar a fonte de verdade de identidade.",
    "whyWrong": {
     "A": "Criar 3.000 usuários IAM manualmente é o oposto de menor esforço operacional, e sincronizar senha com o AD manualmente introduz um segundo sistema de verdade que diverge com o tempo.",
     "B": "Migrar TODA a base para o Directory Service é uma mudança de infraestrutura desproporcional ao requisito, que é só de ACESSO ao console — não pede substituir o AD existente.",
     "D": "Credencial de administrador compartilhada elimina toda rastreabilidade individual e viola o princípio de menor privilégio — é o anti-padrão mais grave da lista."
    },
    "keyConcept": "Federação de identidade com SAML 2.0 e IAM Identity Center"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
