INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-secure-architectures-v1-004', 'aws-saa', 'Uma política IAM anexada a um usuário permite `s3:GetObject` no bucket X. O bucket X tem uma política de recurso que NEGA explicitamente esse mesmo usuário. O que acontece quando ele tenta ler o objeto?',
  '[{"id":"A","text":"A permissão é concedida, porque a política de identidade tem prioridade"},{"id":"B","text":"A AWS pede confirmação manual antes de decidir"},{"id":"C","text":"O resultado depende da ordem em que as políticas foram criadas"},{"id":"D","text":"O acesso é negado — um DENY explícito em qualquer política (identidade ou recurso) sempre vence sobre um ALLOW"}]'::jsonb, 'D',
  '{
    "summary": "A avaliação de política IAM segue uma regra fixa, e DENY explícito é a exceção mais alta da hierarquia.",
    "whyCorrect": "O algoritmo de avaliação combina TODAS as políticas aplicáveis (identidade, recurso, SCP, permission boundary). Se qualquer uma delas contém um DENY explícito para a ação, o resultado final é negação — independentemente de quantos ALLOW existam em outras políticas.",
    "whyWrong": {
     "A": "Inverte a regra: não existe hierarquia onde identidade \"vence\" recurso. As duas são avaliadas juntas, e um DENY em qualquer uma decide o resultado.",
     "B": "A avaliação é inteiramente automática e determinística; não há passo de confirmação manual no controle de acesso da AWS.",
     "C": "Ordem de criação não influencia avaliação de política — o motor de avaliação olha o CONTEÚDO vigente das políticas no momento da chamada, não o histórico de quando foram escritas."
    },
    "keyConcept": "Avaliação de política IAM: DENY explícito sempre vence"
   }'::jsonb,
  '', '', 'easy', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
