INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-secure-architectures-v1-005', 'aws-saa', 'Uma startup tem uma única conta AWS de produção e quer preparar a governança para quando crescer para dezenas de contas — sem reconstruir tudo depois. Qual prática deve adotar agora?',
  '[{"id":"A","text":"Adotar AWS Organizations com uma estrutura de OUs e AWS Control Tower desde a conta única, mesmo que hoje só exista uma conta de carga de trabalho"},{"id":"B","text":"Aguardar até ter múltiplas contas para pensar em governança"},{"id":"C","text":"Criar um usuário root separado para cada futuro serviço"},{"id":"D","text":"Usar apenas tags de recurso para simular isolamento entre times"}]'::jsonb, 'A',
  '{
    "summary": "Estrutura organizacional migra melhor quando existe DESDE O INÍCIO do que quando é retrofitada sobre dezenas de contas já em uso.",
    "whyCorrect": "AWS Organizations e Control Tower estabelecem a landing zone — OUs, SCPs base, conta de log centralizado — que absorve novas contas conforme a empresa cresce, sem exigir migração disruptiva de cargas já em produção.",
    "whyWrong": {
     "B": "Esperar significa migrar dezenas de contas já em produção para uma estrutura organizacional depois — ordem de grandeza mais caro e arriscado do que nascer com ela.",
     "C": "Múltiplas credenciais root são o oposto de governança: cada root tem poder irrestrito e nenhuma centralização de controle, e a AWS recomenda proteger e usar o mínimo possível o root de CADA conta.",
     "D": "Tag é metadado, não fronteira de segurança. Ela ajuda em custo e organização visual, mas não isola permissão nem impede que um recurso de um time seja acessado por outro."
    },
    "keyConcept": "AWS Organizations e Control Tower como base de governança multi-conta"
   }'::jsonb,
  '', '', 'hard', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
