INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-secure-architectures-v1-006', 'aws-saa', 'Um desenvolvedor recebeu uma permission boundary que limita suas ações a `s3:*` e `dynamodb:*`. A política IAM anexada a ele, no entanto, concede também `ec2:*`. O que ele consegue fazer com EC2?',
  '[{"id":"A","text":"Tudo que a política IAM permite, porque a boundary só se aplica a novas políticas"},{"id":"B","text":"Nada em EC2 — a permission boundary é o teto efetivo, e a interseção entre ela e a política de identidade é o que vale"},{"id":"C","text":"Metade das ações de EC2, escolhidas aleatoriamente"},{"id":"D","text":"Depende de qual política foi criada por último"}]'::jsonb, 'B',
  '{
    "summary": "Permission boundary define o TETO máximo possível, e o resultado efetivo é sempre a interseção entre ela e a política de identidade.",
    "whyCorrect": "A permissão efetiva de um usuário é a interseção entre o que a política de identidade concede e o que a permission boundary permite. Como a boundary não inclui `ec2:*`, nenhuma ação de EC2 passa, mesmo estando na política de identidade.",
    "whyWrong": {
     "A": "A boundary se aplica a QUALQUER ação do usuário, existente ou nova — ela não é retroativamente ignorada para políticas já anexadas.",
     "C": "Não há resultado parcial aleatório: a avaliação de IAM é determinística e binária por ação — permitida ou negada, nunca \"meio permitida\".",
     "D": "Assim como no caso de DENY explícito, a ordem de criação não decide o resultado. O que decide é a interseção lógica entre os dois documentos, avaliada a cada chamada."
    },
    "keyConcept": "Permission boundaries como teto de permissão"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
