INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-secure-architectures-v1-007', 'aws-saa', 'Uma aplicação em uma instância EC2 precisa chamar a API do S3. Qual é a prática recomendada para dar essa permissão à aplicação?',
  '[{"id":"A","text":"Gravar uma access key e secret key no código-fonte da aplicação"},{"id":"B","text":"Usar as credenciais pessoais do desenvolvedor que fez o deploy"},{"id":"C","text":"Anexar uma IAM role à instância EC2, via instance profile, com a política mínima necessária para o S3"},{"id":"D","text":"Desabilitar autenticação para o bucket usado por essa aplicação"}]'::jsonb, 'C',
  '{
    "summary": "Instância EC2 chamando serviço AWS é o caso canônico de instance profile, não de credencial embutida.",
    "whyCorrect": "A role anexada via instance profile entrega credenciais TEMPORÁRIAS à instância através do serviço de metadados, rotacionadas automaticamente pela AWS — sem nenhuma chave fixa armazenada em disco ou em código.",
    "whyWrong": {
     "A": "Chave gravada no código é o antipadrão mais citado em toda a certificação: ela vaza em repositório, em log e em imagem de contêiner, e não expira sozinha.",
     "B": "Credencial pessoal amarra a aplicação à conta de uma pessoa específica — se ela sai da empresa ou tem a senha trocada, a aplicação quebra, e não há rastreabilidade de que a chamada veio da aplicação.",
     "D": "Desabilitar autenticação do bucket expõe os dados a qualquer um, resolvendo o problema de acesso da aplicação criando um problema de segurança muito maior."
    },
    "keyConcept": "IAM role para EC2 via instance profile"
   }'::jsonb,
  '', '', 'easy', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
