INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-secure-architectures-v1-008', 'aws-saa', 'Uma arquitetura de três camadas precisa que só o Application Load Balancer receba tráfego da internet, e que as instâncias da camada de aplicação só aceitem tráfego vindo do ALB — nunca diretamente da internet. Qual configuração de rede implementa isso?',
  '[{"id":"A","text":"Colocar todas as camadas na mesma sub-rede pública"},{"id":"B","text":"Abrir a porta da aplicação para 0.0.0.0/0 e confiar no antivírus da instância"},{"id":"C","text":"Usar apenas Network ACL, sem security group"},{"id":"D","text":"ALB em sub-rede pública; instâncias de aplicação em sub-rede privada, com security group que permite entrada apenas do security group do ALB"}]'::jsonb, 'D',
  '{
    "summary": "Segmentação em camadas de sub-rede, com security group referenciando outro security group, é o padrão de isolamento em VPC.",
    "whyCorrect": "Colocar as instâncias de aplicação numa sub-rede PRIVADA já as torna inalcançáveis diretamente da internet, e um security group que aceita entrada apenas do security group do ALB garante que só o load balancer — nunca outra origem — alcance a porta da aplicação.",
    "whyWrong": {
     "A": "Sub-rede pública dá rota direta à internet para todas as camadas, o oposto do requisito de que só o ALB seja exposto.",
     "B": "Abrir para 0.0.0.0/0 expõe a aplicação a qualquer origem na internet, e antivírus de instância não substitui controle de rede — é uma camada diferente de defesa, tardia demais para este requisito.",
     "C": "Network ACL sozinha é sem estado e opera por sub-rede inteira, não por instância; ela não expressa \"só aceite tráfego do ALB\" com a granularidade que security group oferece."
    },
    "keyConcept": "Segmentação de VPC e security group referenciando security group"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
