INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-secure-architectures-v1-009', 'aws-saa', 'Uma aplicação web pública sofre tentativas recorrentes de SQL injection e scanning automatizado. Qual serviço gerenciado da AWS mitiga isso na borda, antes do tráfego chegar à aplicação?',
  '[{"id":"A","text":"AWS WAF, com regras gerenciadas contra SQL injection e bots conhecidos"},{"id":"B","text":"AWS Shield Standard, que já é ativado por padrão"},{"id":"C","text":"Amazon GuardDuty, analisando os logs depois do ataque"},{"id":"D","text":"AWS Config, auditando a configuração dos recursos"}]'::jsonb, 'A',
  '{
    "summary": "WAF é o serviço de FILTRO de camada de aplicação — é ele que inspeciona o conteúdo da requisição.",
    "whyCorrect": "O AWS WAF inspeciona o corpo e os cabeçalhos da requisição HTTP e pode bloquear padrões de SQL injection, XSS e bots conhecidos ANTES de a requisição alcançar o servidor de aplicação, usando regras gerenciadas mantidas pela AWS.",
    "whyWrong": {
     "B": "Shield Standard protege contra DDoS de rede e transporte (camadas 3/4), não contra payload malicioso dentro de uma requisição HTTP válida — é outro tipo de ameaça.",
     "C": "GuardDuty é DETECTIVO: ele analisa comportamento e gera achado depois que algo aconteceu. O requisito pede mitigação na borda, antes do impacto.",
     "D": "Config avalia se recursos estão configurados conforme regra — ele não inspeciona tráfego de aplicação nem bloqueia requisição alguma."
    },
    "keyConcept": "AWS WAF contra ataques de camada de aplicação",
    "compareWith": [
     "WAF vs Shield vs GuardDuty — filtro, DDoS e detecção são três problemas distintos"
    ]
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
