INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-secure-architectures-v1-010', 'aws-saa', 'Uma filial da empresa precisa de conectividade privada e consistente entre o data center on-premises e a VPC na AWS, com throughput garantido e sem depender da internet pública. Qual opção de conectividade atende?',
  '[{"id":"A","text":"Uma VPN Site-to-Site sobre a internet pública"},{"id":"B","text":"AWS Direct Connect, com um circuito dedicado até a AWS"},{"id":"C","text":"Abrir todas as portas do Security Group para o IP da filial"},{"id":"D","text":"Usar apenas endpoints públicos do S3"}]'::jsonb, 'B',
  '{
    "summary": "Direct Connect é a única opção que oferece link FÍSICO dedicado, fora da internet pública.",
    "whyCorrect": "Direct Connect estabelece uma conexão de rede dedicada entre o data center e a AWS, com largura de banda consistente e sem trafegar pela internet pública — é a resposta quando o requisito nomeia throughput garantido e consistência.",
    "whyWrong": {
     "A": "VPN Site-to-Site cifra o tráfego, mas ainda trafega SOBRE a internet pública, herdando a variabilidade de latência e throughput dela — não atende \"sem depender da internet pública\".",
     "C": "Abrir porta por IP de origem é controle de firewall, não conectividade de rede — não estabelece o link físico nem melhora throughput ou consistência.",
     "D": "Endpoint público de S3 resolve acesso a UM serviço específico pela internet; não é conectividade de rede entre data center e VPC, e não atende o requisito de link privado e consistente."
    },
    "keyConcept": "AWS Direct Connect para conectividade híbrida dedicada"
   }'::jsonb,
  '', '', 'hard', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
