INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-secure-architectures-v1-011', 'aws-saa', 'Uma aplicação em uma sub-rede privada precisa baixar atualizações de pacotes de repositórios na internet, mas NUNCA deve aceitar conexão iniciada de fora. Qual componente de rede atende?',
  '[{"id":"A","text":"Internet Gateway anexado diretamente à sub-rede privada"},{"id":"B","text":"Abrir a sub-rede privada inteira para 0.0.0.0/0 de entrada"},{"id":"C","text":"NAT Gateway numa sub-rede pública, com rota da sub-rede privada apontando para ele"},{"id":"D","text":"Nenhum componente — a instância privada já tem acesso à internet por padrão"}]'::jsonb, 'C',
  '{
    "summary": "NAT Gateway permite saída sem permitir entrada — exatamente a assimetria que o requisito pede.",
    "whyCorrect": "O NAT Gateway fica numa sub-rede pública e traduz o endereço de origem das conexões INICIADAS pela instância privada, permitindo que ela alcance a internet para baixar pacotes — sem que nenhuma conexão de fora consiga iniciar contato com ela.",
    "whyWrong": {
     "A": "Internet Gateway numa sub-rede privada a tornaria efetivamente pública, permitindo tanto saída quanto ENTRADA de conexão — o oposto do requisito de nunca aceitar conexão de fora.",
     "B": "Abrir 0.0.0.0/0 de entrada é exatamente o que o requisito proíbe — criaria a superfície de ataque que o NAT Gateway existe para evitar.",
     "D": "Sub-rede privada, por definição, não tem rota padrão para a internet; sem um componente como o NAT Gateway, ela simplesmente não alcança a internet nenhuma."
    },
    "keyConcept": "NAT Gateway e o padrão de saída sem entrada"
   }'::jsonb,
  '', '', 'easy', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
