INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-secure-architectures-v1-012', 'aws-saa', 'Uma API deve ser acessada apenas por aplicações dentro da própria VPC da empresa, nunca pela internet pública, mesmo que o serviço backend seja um serviço gerenciado da AWS. Qual recurso viabiliza isso sem expor a chamada à internet?',
  '[{"id":"A","text":"Um endpoint público do serviço, protegido só por IAM"},{"id":"B","text":"Um NAT Gateway configurado como proxy reverso"},{"id":"C","text":"Desabilitar o DNS público da VPC"},{"id":"D","text":"Um VPC endpoint (interface ou gateway) para o serviço, mantendo o tráfego dentro da rede da AWS"}]'::jsonb, 'D',
  '{
    "summary": "VPC endpoint é o mecanismo desenhado especificamente para alcançar serviço AWS sem sair para a internet.",
    "whyCorrect": "Um VPC endpoint cria um caminho privado entre a VPC e o serviço AWS, dentro da rede da própria AWS — a chamada nunca atravessa a internet pública, mesmo que o serviço backend seja, por natureza, um endpoint regional gerenciado.",
    "whyWrong": {
     "A": "Endpoint público, mesmo com IAM controlando QUEM chama, ainda trafega pela internet pública para chegar até ele — o requisito é sobre o CAMINHO da rede, não só sobre autorização.",
     "B": "NAT Gateway serve para tráfego de SAÍDA de sub-rede privada até a internet; ele não é o mecanismo de acesso privado a um serviço AWS gerenciado, e usá-lo como proxy reverso não é seu propósito.",
     "C": "Desabilitar DNS público muda resolução de nome, não o caminho de rede da chamada — a chamada continuaria saindo para a internet se não houver um endpoint privado configurado."
    },
    "keyConcept": "VPC Endpoints (interface e gateway) para acesso privado a serviços AWS"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
