INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-secure-architectures-v1-013', 'aws-saa', 'Uma equipe de segurança quer detectar comportamento anômalo — como uma instância EC2 comprometida se comunicando com um servidor de comando e controle conhecido. Qual serviço é desenhado para isso?',
  '[{"id":"A","text":"Amazon GuardDuty, que analisa logs de VPC Flow, DNS e CloudTrail com inteligência de ameaça"},{"id":"B","text":"AWS Config"},{"id":"C","text":"AWS Trusted Advisor"},{"id":"D","text":"Amazon CloudWatch Logs sozinho, sem nenhuma análise adicional"}]'::jsonb, 'A',
  '{
    "summary": "GuardDuty é o serviço de detecção de ameaça com inteligência de ameaça integrada, não os outros três.",
    "whyCorrect": "GuardDuty cruza VPC Flow Logs, logs de DNS e eventos do CloudTrail contra feeds de inteligência de ameaça — incluindo listas de IPs de comando e controle conhecidos — e gera achados quando encontra correspondência.",
    "whyWrong": {
     "B": "Config avalia CONFORMIDADE de configuração de recurso contra uma regra declarada; ele não analisa tráfego de rede nem cruza com inteligência de ameaça.",
     "C": "Trusted Advisor dá recomendações de custo, desempenho e boas práticas gerais; não é uma ferramenta de detecção de ameaça em tempo real.",
     "D": "CloudWatch Logs sozinho é armazenamento e consulta de log — ele não tem a camada de inteligência de ameaça que cruza automaticamente com IPs maliciosos conhecidos; isso é o que o GuardDuty acrescenta por cima."
    },
    "keyConcept": "Amazon GuardDuty e detecção de ameaça com inteligência integrada"
   }'::jsonb,
  '', '', 'easy', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
