INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-secure-architectures-v1-014', 'aws-saa', 'Uma empresa do setor financeiro precisa identificar automaticamente CPFs e números de cartão de crédito armazenados em buckets S3, para atender a um requisito de conformidade. Qual serviço da AWS foi desenhado para isso?',
  '[{"id":"A","text":"AWS Certificate Manager"},{"id":"B","text":"Amazon Macie"},{"id":"C","text":"Amazon Inspector"},{"id":"D","text":"AWS Secrets Manager"}]'::jsonb, 'B',
  '{
    "summary": "Macie é o serviço de descoberta e classificação de dado sensível em S3.",
    "whyCorrect": "O Macie usa aprendizado de máquina e padrões pré-configurados para varrer buckets S3 e identificar dado sensível como CPF, número de cartão e outra informação de identificação pessoal, gerando um inventário do que precisa de controle extra.",
    "whyWrong": {
     "A": "Certificate Manager provisiona e gerencia certificados TLS; não tem relação com classificação de conteúdo de dado.",
     "C": "Inspector avalia vulnerabilidade em carga de trabalho de computação — pacotes desatualizados, exposição de rede; ele não varre conteúdo de objeto em busca de dado sensível.",
     "D": "Secrets Manager armazena e rotaciona segredo como senha de banco de dados; é sobre PROTEGER um segredo conhecido, não sobre DESCOBRIR dado sensível espalhado em buckets."
    },
    "keyConcept": "Amazon Macie para descoberta de dado sensível"
   }'::jsonb,
  '', '', 'easy', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
