INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-secure-architectures-v1-015', 'aws-saa', 'Uma empresa precisa que os dados em um bucket S3 sejam cifrados em repouso, com controle total sobre a chave — incluindo a capacidade de revogar acesso à chave imediatamente e de auditar cada uso dela. Qual opção de cifra atende?',
  '[{"id":"A","text":"SSE-S3, com chave gerenciada inteiramente pela AWS"},{"id":"B","text":"Deixar o bucket sem cifra e confiar no controle de acesso do IAM"},{"id":"C","text":"SSE-KMS com uma chave gerenciada pelo cliente (CMK), permitindo política de chave própria e registro de uso no CloudTrail"},{"id":"D","text":"Cifrar os dados no cliente antes do upload, sem nenhum uso do KMS"}]'::jsonb, 'C',
  '{
    "summary": "O requisito de CONTROLE e AUDITORIA da chave aponta para KMS com chave gerenciada pelo cliente, não pela AWS.",
    "whyCorrect": "Uma CMK do KMS permite que o cliente defina a política da chave, revogue permissão de uso a qualquer momento e veja cada operação de cifra/decifra registrada no CloudTrail — exatamente o nível de controle e auditoria que SSE-S3 (chave da AWS) não oferece.",
    "whyWrong": {
     "A": "SSE-S3 usa chave TOTALMENTE gerenciada pela AWS: o cliente não define política de chave própria nem revoga acesso a ela diretamente — cifra os dados, mas sem o controle que o requisito pede.",
     "B": "Ausência de cifra não atende a nenhuma parte do requisito, e controle de acesso IAM protege quem CHAMA a API, não o estado do dado em repouso no disco.",
     "D": "Cifrar no cliente sem KMS resolve confidencialidade, mas perde justamente o que o requisito pede — revogação centralizada e trilha de auditoria de uso da chave, que é o papel do KMS."
    },
    "keyConcept": "SSE-S3 vs SSE-KMS: controle e auditoria de chave"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
