INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-secure-architectures-v1-016', 'aws-saa', 'Uma aplicação envia dados sensíveis entre o navegador do cliente e um Application Load Balancer. Qual configuração garante que esse tráfego seja cifrado em trânsito, com certificado gerenciado e renovado automaticamente pela AWS?',
  '[{"id":"A","text":"Configurar um listener HTTP simples na porta 80"},{"id":"B","text":"Pedir ao usuário que ative \"conexão segura\" no navegador"},{"id":"C","text":"Cifrar o corpo da requisição manualmente no JavaScript do cliente"},{"id":"D","text":"Configurar um listener HTTPS no ALB com um certificado emitido pelo AWS Certificate Manager (ACM)"}]'::jsonb, 'D',
  '{
    "summary": "HTTPS com certificado do ACM é o padrão para cifra em trânsito com renovação automática.",
    "whyCorrect": "Um listener HTTPS no ALB, usando certificado emitido e renovado automaticamente pelo ACM, cifra toda a comunicação entre o cliente e o load balancer via TLS — sem que a equipe precise gerenciar renovação manual de certificado.",
    "whyWrong": {
     "A": "Listener HTTP na porta 80 trafega em texto claro; não há cifra nenhuma nesse caminho, o oposto do requisito.",
     "B": "Não existe configuração de navegador do lado do CLIENTE que force cifra num servidor que não a oferece — a decisão de cifrar é do lado do servidor, no listener.",
     "C": "Cifrar manualmente no JavaScript é frágil, não cobre cabeçalhos HTTP nem metadados da conexão, e reinventa algo que o TLS do ACM já resolve de forma auditada e padronizada."
    },
    "keyConcept": "TLS via ACM em Application Load Balancer"
   }'::jsonb,
  '', '', 'easy', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
