INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-secure-architectures-v1-017', 'aws-saa', 'Uma empresa precisa que backups de um banco de dados crítico sobrevivam a uma falha REGIONAL inteira da AWS, e que a chave de cifra usada nesses backups também esteja disponível fora da região afetada. O que a arquitetura deve incluir?',
  '[{"id":"A","text":"Replicação de snapshots para uma segunda região, com a CMK do KMS replicada como multi-region key"},{"id":"B","text":"Snapshots automáticos mantidos apenas na região primária"},{"id":"C","text":"Backups mantidos só localmente na instância"},{"id":"D","text":"Aumentar o tamanho do volume EBS"}]'::jsonb, 'A',
  '{
    "summary": "Sobreviver a falha REGIONAL exige que tanto o dado quanto a CHAVE existam fora da região que falhou.",
    "whyCorrect": "Replicar o snapshot para uma segunda região resolve a disponibilidade do dado; usar uma multi-region key do KMS garante que a MESMA chave lógica exista replicada na região de destino, permitindo decifrar o backup lá sem depender da região que falhou.",
    "whyWrong": {
     "B": "Snapshot só na região primária desaparece exatamente no cenário que o requisito descreve — falha da própria região onde ele está armazenado.",
     "C": "Backup local na instância falha junto com a instância e com a própria região; não atende nem o requisito básico de durabilidade, muito menos o de resiliência regional.",
     "D": "Tamanho de volume é uma dimensão de capacidade de armazenamento, sem relação nenhuma com durabilidade de backup entre regiões nem com replicação de chave de cifra."
    },
    "keyConcept": "Multi-region KMS keys e disaster recovery entre regiões"
   }'::jsonb,
  '', '', 'hard', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
  stem          = EXCLUDED.stem,
