INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-secure-architectures-v1-018', 'aws-saa', 'Uma política de retenção exige que objetos em um bucket S3 não possam ser excluídos ou sobrescritos por NINGUÉM, incluindo o administrador da conta, durante 7 anos, para atender a uma exigência regulatória. Qual recurso do S3 atende?',
  '[{"id":"A","text":"Versionamento do bucket, sozinho"},{"id":"B","text":"S3 Object Lock em modo Compliance, com retenção de 7 anos"},{"id":"C","text":"Uma política de bucket negando DeleteObject para todos"},{"id":"D","text":"Fazer backup manual mensal em outro bucket"}]'::jsonb, 'B',
  '{
    "summary": "O modo Compliance do Object Lock é o único que impede exclusão mesmo pelo root/administrador da conta durante o período de retenção.",
    "whyCorrect": "O S3 Object Lock em modo Compliance bloqueia a exclusão ou sobrescrita do objeto até o fim do período de retenção configurado — e, ao contrário do modo Governance, nem o usuário root da conta consegue remover essa proteção antes do prazo.",
    "whyWrong": {
     "A": "Versionamento sozinho permite recuperar uma versão anterior, mas não IMPEDE a exclusão — um DeleteObject ainda cria um delete marker, e versões antigas continuam apagáveis por quem tiver permissão.",
     "C": "Uma política de bucket pode ser ALTERADA por quem tem permissão de `s3:PutBucketPolicy` — inclusive um administrador. Ela não é imutável da forma que o requisito regulatório exige.",
     "D": "Backup manual mensal depende de disciplina humana recorrente, não impede exclusão do original entre um backup e outro, e não atende a uma exigência de imutabilidade regulatória verificável."
    },
    "keyConcept": "S3 Object Lock — modo Compliance vs Governance"
   }'::jsonb,
  '', '', 'hard', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
