INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-secure-architectures-v1-019', 'aws-saa', 'Uma aplicação processa dados de cartão de crédito e precisa alternar (rotacionar) a credencial do banco de dados a cada 30 dias, sem que a aplicação precise ser reiniciada manualmente a cada rotação. Qual serviço resolve isso de forma gerenciada?',
  '[{"id":"A","text":"Armazenar a senha em uma variável de ambiente fixa"},{"id":"B","text":"Gravar a senha em um arquivo de texto no S3"},{"id":"C","text":"AWS Secrets Manager, com rotação automática configurada via Lambda"},{"id":"D","text":"Pedir para o time de banco trocar a senha manualmente todo mês e avisar por e-mail"}]'::jsonb, 'C',
  '{
    "summary": "Rotação automática e recorrente de segredo é exatamente o propósito do Secrets Manager.",
    "whyCorrect": "O Secrets Manager rotaciona a credencial automaticamente numa função Lambda que atualiza tanto o segredo armazenado quanto o próprio banco de dados na mesma operação — a aplicação busca o segredo atual em runtime, sem reinício manual coordenado com a rotação.",
    "whyWrong": {
     "A": "Variável de ambiente fixa exige redeploy da aplicação toda vez que a senha muda — o oposto de rotação sem intervenção manual.",
     "B": "Arquivo de texto no S3 não tem mecanismo de rotação nem de cifra dedicado a segredo, e ainda expõe a credencial em texto claro a quem tiver acesso de leitura ao bucket.",
     "D": "Processo manual mensal com aviso por e-mail depende de disciplina humana recorrente e tem alto risco de esquecimento ou de dessincronia entre o banco e o que a aplicação usa — exatamente o que a automação evita."
    },
    "keyConcept": "AWS Secrets Manager e rotação automática de credencial"
   }'::jsonb,
  '', '', 'easy', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
