INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'saa-c03-secure-architectures-v1-020', 'aws-saa', 'Uma equipe de auditoria precisa provar, para um regulador, quais chamadas de API foram feitas em toda a organização nos últimos 2 anos, incluindo em contas que já foram fechadas. Qual configuração atende com menor esforço?',
  '[{"id":"A","text":"Confiar apenas no CloudTrail Event History de 90 dias de cada conta"},{"id":"B","text":"Pedir para cada conta exportar seus próprios logs manualmente todo mês"},{"id":"C","text":"Depender do histórico de console de cada usuário"},{"id":"D","text":"Um trail organizacional do CloudTrail, com destino em um bucket S3 centralizado de uma conta de log dedicada, com retenção configurada para o prazo exigido"}]'::jsonb, 'D',
  '{
    "summary": "Auditoria multi-conta e de longo prazo exige trail organizacional centralizado, não o histórico padrão de 90 dias.",
    "whyCorrect": "Um trail organizacional captura eventos de TODAS as contas da organização — inclusive contas futuras criadas depois — e os grava num bucket S3 centralizado numa conta de log dedicada, com a retenção que a auditoria exigir, sobrevivendo até ao fechamento de contas membro.",
    "whyWrong": {
     "A": "O Event History do console mostra só os últimos 90 dias e é por conta individual — não cobre 2 anos nem contas já fechadas, que é exatamente o que a auditoria pede.",
     "B": "Exportação manual mensal por conta é operacionalmente frágil, sujeita a esquecimento, e não escala para \"todas as contas, incluindo futuras\" sem processo humano recorrente.",
     "C": "Histórico de console é uma trilha de navegação da interface, não um registro de chamada de API — não é o que o CloudTrail audita nem o que um regulador aceitaria como evidência."
    },
    "keyConcept": "CloudTrail organizacional e retenção de longo prazo para auditoria"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
